window.CC.p.push({n:6,view:"<section class=\"view\" id=\"p6\" hidden style=\"--c:#00897b\"><h1><i>6</i>Pediatrics</h1><p class=\"lead\">30 sections — pick what you want to read.</p><div class=\"grid\"><h3 class=\"sg\">Part 6A</h3><div class=\"card\" data-u=\"u112\"><button class=\"open\" data-u=\"u112\"><b>Case 1</b><span>Neonatal Jaundice (HYPERBILIRUBINEMIA)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Neonatal+Jaundice+%28HYPERBILIRUBINEMIA%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u113\"><button class=\"open\" data-u=\"u113\"><b>Case 2</b><span>Neonatal Sepsis</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Neonatal+Sepsis\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u114\"><button class=\"open\" data-u=\"u114\"><b>Case 3</b><span>Neonatal RDS (HYALINE MEMBRANE DISEASE) vs. TTN</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Neonatal+RDS+%28HYALINE+MEMBRANE+DISEASE%29+vs.+TTN\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u115\"><button class=\"open\" data-u=\"u115\"><b>Case 4</b><span>Acute Bronchiolitis</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Bronchiolitis\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u116\"><button class=\"open\" data-u=\"u116\"><b>Case 5</b><span>Croup (LARYNGOTRACHEOBRONCHITIS) vs. Acute Epiglottitis</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Croup+%28LARYNGOTRACHEOBRONCHITIS%29+vs.+Acute+Epiglottitis\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u117\"><button class=\"open\" data-u=\"u117\"><b>Case 6</b><span>Pediatric Community-Acquired Pneumonia (CAP)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pediatric+Community-Acquired+Pneumonia+%28CAP%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u118\"><button class=\"open\" data-u=\"u118\"><b>Case 7</b><span>Pediatric Bronchial Asthma</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pediatric+Bronchial+Asthma\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u119\"><button class=\"open\" data-u=\"u119\"><b>Case 8</b><span>Foreign Body Aspiration (FBA)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Foreign+Body+Aspiration+%28FBA%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u120\"><button class=\"open\" data-u=\"u120\"><b>Case 9</b><span>Acute Pediatric Gastroenteritis &amp; Dehydration (WHO / IMCI PROTOCOL)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Pediatric+Gastroenteritis+%26+Dehydration+%28WHO+%2F+IMCI+PROTOCOL%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u121\"><button class=\"open\" data-u=\"u121\"><b>Case 10</b><span>Infantile Hypertrophic Pyloric Stenosis</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Infantile+Hypertrophic+Pyloric+Stenosis\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u122\"><button class=\"open\" data-u=\"u122\"><b>Case 11</b><span>Intussusception</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Intussusception\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u123\"><button class=\"open\" data-u=\"u123\"><b>Case 12</b><span>Malrotation with Midgut Volvulus &amp; Hirschsprung Disease</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Malrotation+with+Midgut+Volvulus+%26+Hirschsprung+Disease\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u124\"><button class=\"open\" data-u=\"u124\"><b>Case 13</b><span>Infantile Gastroesophageal Reflux (GER) vs. Cmpa</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Infantile+Gastroesophageal+Reflux+%28GER%29+vs.+Cmpa\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u125\"><button class=\"open\" data-u=\"u125\"><b>Case 14</b><span>Nutritional Rickets &amp; Pediatric Iron Deficiency Anemia (IDA)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Nutritional+Rickets+%26+Pediatric+Iron+Deficiency+Anemia+%28IDA%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u126\"><button class=\"open\" data-u=\"u126\"><b>Case 15</b><span>Failure to Thrive (FTT) &amp; Severe Acute Malnutrition</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Failure+to+Thrive+%28FTT%29+%26+Severe+Acute+Malnutrition\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><h3 class=\"sg\">Part 6B</h3><div class=\"card\" data-u=\"u127\"><button class=\"open\" data-u=\"u127\"><b>Case 16</b><span>Febrile Seizures &amp; Pediatric Status Epilepticus</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Febrile+Seizures+%26+Pediatric+Status+Epilepticus\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u128\"><button class=\"open\" data-u=\"u128\"><b>Case 17</b><span>Pediatric Bacterial Meningitis &amp; Encephalitis</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pediatric+Bacterial+Meningitis+%26+Encephalitis\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u129\"><button class=\"open\" data-u=\"u129\"><b>Case 18</b><span>Acute Rheumatic Fever (ARF — PEDIATRIC MANAGEMENT)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Rheumatic+Fever+%28ARF+%E2%80%94+PEDIATRIC+MANAGEMENT%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u130\"><button class=\"open\" data-u=\"u130\"><b>Case 19</b><span>Kawasaki Disease (MUCOCUTANEOUS LYMPH NODE SYNDROME)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Kawasaki+Disease+%28MUCOCUTANEOUS+LYMPH+NODE+SYNDROME%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u131\"><button class=\"open\" data-u=\"u131\"><b>Case 20</b><span>Henoch-Schönlein Purpura (HSP / IgA VASCULITIS)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Henoch-Sch%C3%B6nlein+Purpura+%28HSP+%2F+IgA+VASCULITIS%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u132\"><button class=\"open\" data-u=\"u132\"><b>Case 21</b><span>Classic Childhood Viral Exanthems &amp; Scarlet Fever</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Classic+Childhood+Viral+Exanthems+%26+Scarlet+Fever\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u133\"><button class=\"open\" data-u=\"u133\"><b>Case 22</b><span>Mumps &amp; Pertussis (WHOOPING COUGH)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Mumps+%26+Pertussis+%28WHOOPING+COUGH%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u134\"><button class=\"open\" data-u=\"u134\"><b>Case 23</b><span>Pediatric Urinary Tract Infection (UTI) &amp; VUR</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pediatric+Urinary+Tract+Infection+%28UTI%29+%26+VUR\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u135\"><button class=\"open\" data-u=\"u135\"><b>Case 24</b><span>Pediatric Nephrotic Syndrome (MINIMAL CHANGE DISEASE)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pediatric+Nephrotic+Syndrome+%28MINIMAL+CHANGE+DISEASE%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u136\"><button class=\"open\" data-u=\"u136\"><b>Case 25</b><span>Acute Post-Streptococcal Glomerulonephritis (PSGN)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Post-Streptococcal+Glomerulonephritis+%28PSGN%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u137\"><button class=\"open\" data-u=\"u137\"><b>Case 26</b><span>Pediatric Immune Thrombocytopenic Purpura (ITP)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pediatric+Immune+Thrombocytopenic+Purpura+%28ITP%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u138\"><button class=\"open\" data-u=\"u138\"><b>Case 27</b><span>Beta-Thalassemia Major, Sickle Cell Disease &amp; G6PD Deficiency (EGYPTIAN HEME CLASSICS)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Beta-Thalassemia+Major%2C+Sickle+Cell+Disease+%26+G6PD+Deficiency+%28EGYPTIAN+HEME+CLASSICS%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u139\"><button class=\"open\" data-u=\"u139\"><b>Case 28</b><span>Acute Lymphoblastic Leukemia (ALL — PEDIATRIC RED FLAGS)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Lymphoblastic+Leukemia+%28ALL+%E2%80%94+PEDIATRIC+RED+FLAGS%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u140\"><button class=\"open\" data-u=\"u140\"><b>Case 29</b><span>Congenital Heart Diseases (VSD, ASD, PDA &amp; TETRALOGY OF FALLOT)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Congenital+Heart+Diseases+%28VSD%2C+ASD%2C+PDA+%26+TETRALOGY+OF+FALLOT%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u141\"><button class=\"open\" data-u=\"u141\"><b>Case 30</b><span>Pediatric Type 1 Diabetes Mellitus (T1DM) &amp; Pediatric DKA</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pediatric+Type+1+Diabetes+Mellitus+%28T1DM%29+%26+Pediatric+DKA\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div></div></section>",units:"<article class=\"view unit\" id=\"u112\" hidden style=\"--c:#00897b\"><button class=\"back\" data-p=\"6\">← Pediatrics</button><header class=\"uh\"><span class=\"ul\">Case 1</span><h1>Neonatal Jaundice (HYPERBILIRUBINEMIA)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Neonatal+Jaundice+%28HYPERBILIRUBINEMIA%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Yellowish discoloration of the skin and sclera in a newborn caused by elevated serum bilirubin (<b>&gt; 5 mg/dL</b> clinically visible), progressing cephalocaudally (face -&gt; trunk -&gt; extremities -&gt; palms/soles).</p><h3><b>2. Etiology (Separated — Physiologic vs. Pathologic)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Physiologic Jaundice (~60% of term, ~80% of preterm newborns):</b></span></p>\n<ul>\n<li class=\"l2\"><i>Causes:</i> Increased fetal <b>RBC</b> (Red Blood Cell) turnover + shorter neonatal RBC lifespan (70–90 days) + immature hepatic <b>UGT</b> (Uridine Diphosphate Glucuronosyltransferase) enzyme + increased enterohepatic circulation.</li>\n<li class=\"l2\"><i>Rules:</i> Appears <b>AFTER 24 hours</b> (Day 2–3), peaks Day 3–5, <b>unconjugated (indirect)</b>, resolves by Day 7–14, baby is thriving!</li>\n</ul><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><p><mark class=\"hl red\"><b>⚠ Pathologic Unconjugated Hyperbilirubinemia (\"RED FLAGS\" — Needs Urgent Evaluation!):</b></mark></p></div></div><p>2.</p><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><ul>\n<li class=\"l2\"><i>Appears </i><i><b>&lt; 24 hours of age</b></i><i>:</i> <b>Hemolytic Disease of the Newborn</b> (<b>ABO incompatibility</b> [Mother O, Baby A/B], <b>Rh incompatibility</b> [Mother Rh-, Baby Rh+]), <b>G6PD Deficiency</b> (very common in Egypt!), Hereditary Spherocytosis, Sepsis.</li>\n<li class=\"l2\"><i>Exaggerated / Prolonged (&gt; 14 days in term, &gt; 21 days in preterm):</i> <b>Breastfeeding Jaundice</b> (early inadequate milk intake -&gt; dehydration/delayed meconium), <b>Breast Milk Jaundice</b> (starts Day 5–7, benign, peaks Week 2–3 due to β-glucuronidase in milk), <mark class=\"hl lab\"><b>Congenital Hypothyroidism</b></mark> , <b>Crigler-Najjar / Gilbert</b> syndrome, Cephalohematoma resorption.</li>\n</ul></div></div><p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Pathologic Conjugated (Direct) Hyperbilirubinemia (Direct Bilirubin &gt; 1.0 mg/dL OR &gt; 20% of total — ALWAYS PATHOLOGIC!</b>):**</span></p>\n<ul>\n<li class=\"l2\"><b>Biliary Atresia</b> (pale/acholic clay stools + dark urine — <b>MUST operate [Kasai procedure] before 60 days of life!</b>), Neonatal Hepatitis (<b>TORCH</b> infections, Sepsis), Galactosemia, <b>AAT</b> (Alpha-1 Antitrypsin) deficiency.</li>\n</ul><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><p><mark class=\"hl red\"><b>⚠ 3. Clinical Picture &amp; Red Flag Complication</b></mark></p></div></div><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><ul>\n<li class=\"l1\">Examine in bright natural daylight; check stool color (pale clay = biliary atresia!) and hepatosplenomegaly.</li>\n<li class=\"l1\"><b>Complication — Acute Bilirubin Encephalopathy -&gt; Kernicterus:</b> Unconjugated bilirubin crosses blood-brain barrier and deposits in basal ganglia -&gt; lethargy, poor feeding, <b>high-pitched cry</b>, <b>opisthotonos</b> (retrocollis), seizures -&gt; permanent choreoathetoid cerebral palsy &amp; sensorineural deafness!</li>\n</ul></div></div><h3><b>4. Investigations</b></h3><ul>\n<li class=\"l1\"><b>Total &amp; Direct (Conjugated) Serum Bilirubin</b> (TcB transcutaneous screening only; confirm with serum TSB!).</li>\n<li class=\"l1\"><b>Hemolytic Workup:</b> Mother &amp; Baby <b>ABO/Rh blood typing</b>, <b>Direct Coombs Test (DAT)</b>, <mark class=\"hl mech\"><b>CBC + Reticulocyte count + Peripheral smear</b></mark> , <b>G6PD assay</b> (note: may be falsely normal during acute hemolysis!).</li>\n<li class=\"l1\">If prolonged &gt; 2 weeks: <mark class=\"hl mech\"><b>TSH + Free T4</b></mark> , Urine culture, Direct bilirubin.</li>\n</ul><h3><b>5. Treatment (Plot TSB Against Age in Hours on AAP Bhutani Nomogram!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Hydration &amp; Frequent Breastfeeding</b> (8–12 times/day — promotes stooling/bilirubin excretion; do <i>not</i> routinely stop breastfeeding for breast milk jaundice!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><mark class=\"hl rx\"><b>Phototherapy (First-Line):</b></mark> Blue light (<b>460–490 nm</b>) converts insoluble indirect bilirubin into water-soluble <b>lumirubin</b> excreted in bile/urine without conjugation! Protect eyes &amp; genitalia; monitor hydration.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Exchange Transfusion:</b> Emergency treatment if TSB exceeds exchange threshold OR <b>any signs of Acute Bilirubin Encephalopathy</b> exist! (+ <mark class=\"hl rx\"><b>IVIG</b></mark> [Intravenous Immunoglobulin] in severe Rh/ABO isoimmune hemolysis).</span></p><nav class=\"un\"><span></span><button class=\"nv\" data-u=\"u113\">Case 2 →</button></nav></article><article class=\"view unit\" id=\"u113\" hidden style=\"--c:#00897b\"><button class=\"back\" data-p=\"6\">← Pediatrics</button><header class=\"uh\"><span class=\"ul\">Case 2</span><h1>Neonatal Sepsis</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Neonatal+Sepsis\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Systemic bacterial, viral, or fungal bloodstream infection in an infant <b>≤ 28 days old</b>. <b>Medical Emergency — Subtle signs can rapidly progress to septic shock!</b></p><h3><b>2. Etiology (Separated by Age of Onset)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><mark class=\"hl lab\"><b>Early-Onset Neonatal Sepsis (EONS — &lt; 72 Hours of Life, acquired vertically from maternal genital tract):</b></mark></span></p>\n<ul>\n<li class=\"l2\"><i>Pathogens:</i> <mark class=\"hl lab\"><b>GBS</b></mark> (Group B <i>Streptococcus</i> — <i>S. agalactiae</i>), <i><b>Escherichia coli</b></i>, <i>Listeria monocytogenes</i>.</li>\n<li class=\"l2\"><i>Risk Factors:</i> Maternal <b>PROM</b> (Prolonged Rupture of Membranes &gt; 18 hrs), Maternal intrapartum fever / <b>Chorioamnionitis</b>, Prematurity, Maternal GBS colonization.</li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><mark class=\"hl lab\"><b>Late-Onset Neonatal Sepsis (LONS — ≥ 72 Hours to 28 Days, nosocomial/community):</b></mark></span></p>\n<ul>\n<li class=\"l2\"><i>Pathogens:</i> <i>Coagulase-negative Staphylococci</i> (<b>NICU</b> central lines), <i><b>Staphylococcus aureus</b></i>, <i>Klebsiella</i>, <i>Pseudomonas</i>, <i>E. coli</i>, <i>Candida</i>.</li>\n</ul><h3><b>3. Clinical Picture (\"Does Not Look Right\" — Non-Specific!)</b></h3><ul>\n<li class=\"l1\"><b>Temperature instability:</b> <b>Hypothermia</b> (&lt; 36.5°C — MORE common in preterms than fever!) OR <b>Fever (≥ 38.0°C)</b> in a neonate.</li>\n<li class=\"l1\">Poor feeding / weak suck, lethargy or irritability, hypotonia, <b>apnea/bradycardia</b>, tachypnea/grunting, abdominal distension, jaundice, petechiae, mottled skin.</li>\n</ul><h3><b>4. Investigations (Full Septic Workup — Do NOT Delay Antibiotics!)</b></h3><ul>\n<li class=\"l1\"><b>Blood Culture</b> (before antibiotics!), <mark class=\"hl mech\"><b>CBC with Differential</b></mark> (Note: <b>Leukopenia &lt; 5,000</b> or <b>I:T [Immature-to-Total neutrophil] ratio &gt; 0.2</b> is more specific than leukocytosis!), <mark class=\"hl mech\"><b>CRP / Procalcitonin</b></mark> , <b>Urine Culture</b> (suprapubic/catheter in LONS), <mark class=\"hl mech\"><b>Lumbar Puncture (CSF analysis &amp; culture)</b></mark> (especially if LONS, positive blood culture, or neurological signs), <mark class=\"hl mech\"><b>CXR</b></mark> (if respiratory symptoms).</li>\n</ul><h3><b>5. Treatment</b></h3><ul>\n<li class=\"l1\"><b>Admit to NICU + Immediate Empirical IV Antibiotics:</b></li>\n<li class=\"l2\"><b>EONS:</b> <mark class=\"hl rx\"><b>IV Ampicillin + Gentamicin</b></mark> (add <mark class=\"hl rx\"><b>Cefotaxime</b></mark> if meningitis suspected!).</li>\n<li class=\"l2\"><b>LONS (Hospital/NICU):</b> <mark class=\"hl rx\"><b>IV Vancomycin + Gentamicin or Cefotaxime/Meropenem</b></mark> (tailor to unit antibiogram, e.g., Klebsiella/Acinetobacter resistance).</li>\n<li class=\"l1\">Supportive: Fluid boluses (10–20 mL/kg isotonic saline), vasopressors, respiratory support, maintain normoglycemia.</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u112\">← Case 1</button><button class=\"nv\" data-u=\"u114\">Case 3 →</button></nav></article><article class=\"view unit\" id=\"u114\" hidden style=\"--c:#00897b\"><button class=\"back\" data-p=\"6\">← Pediatrics</button><header class=\"uh\"><span class=\"ul\">Case 3</span><h1>Neonatal RDS (HYALINE MEMBRANE DISEASE) vs. TTN</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Neonatal+RDS+%28HYALINE+MEMBRANE+DISEASE%29+vs.+TTN\">🔍 Search on Google</a></header><h4><b>Comparison Table: Two Most Common Causes of Neonatal Respiratory Distress</b></h4><table class=\"t \"><tr class=\"hd\"><th><p><b>Feature</b></p></th><th><p><mark class=\"hl lab\"><b>RDS (Respiratory Distress Syndrome)</b></mark></p></th><th><p><b>TTN (Transient Tachypnea of the Newborn)</b></p></th></tr><tr><td><p><b>Definition &amp; Cause</b></p></td><td><p><mark class=\"hl dx\"><b>Surfactant deficiency</b></mark> causing diffuse alveolar collapse &amp; atelectasis</p></td><td><p><b>Delayed clearance of fetal lung fluid</b> from pulmonary lymphatics</p></td></tr><tr><td><p><b>Classic Neonate</b></p></td><td><p><b>Preterm (&lt; 34–37 weeks)</b>, Maternal Diabetes (insulin delays surfactant), C-section without labor</p></td><td><p><b>Term or Late Preterm</b> delivered via <b>Elective Cesarean Section</b> (no thoracic squeeze!) or precipitous birth</p></td></tr><tr><td><p><b>Onset &amp; Course</b></p></td><td><p>At birth / &lt; 6 hrs; worsens over first 48–72 hrs</p></td><td><p>Within 2 hrs of birth; <b>benign, resolves within 24–72 hrs</b></p></td></tr><tr><td><p><b>Clinical Signs</b></p></td><td><p>Tachypnea, <b>expiratory grunting</b>, nasal flaring, subcostal/intercostal retractions, cyanosis</p></td><td><p>Rapid <b>tachypnea</b> (&gt; 60/min), mild grunting/retractions</p></td></tr><tr><td><p><b>Chest X-Ray</b></p></td><td><p><b>Low lung volumes</b>, diffuse <b>\"Ground-Glass\" (reticulogranular) pattern </b>+ <b>Air Bronchograms</b></p></td><td><p><b>Hyperinflated lungs</b>, prominent perihilar streaking (\"sunburst\"), <b>fluid in horizontal fissure</b></p></td></tr><tr><td><p><b>Treatment</b></p></td><td><p><b>Nasal CPAP</b> immediately + <b>Endotracheal Surfactant</b> (via INSURE/LISA) + antenatal <mark class=\"hl rx\"><b>Betamethasone</b></mark> to mother (24–34 wks) for prevention!</p></td><td><p>Supportive: <b>Low-flow O2</b> (or CPAP) + IV fluids/delayed oral feeds if RR &gt; 70–80/min</p></td></tr></table><p><i>(Note: Also always rule out </i><i><b>Meconium Aspiration Syndrome</b></i><i> [post-term, meconium-stained fluid, patchy infiltrates + hyperinflation], </i><mark class=\"hl lab\"><i><b>Congenital Pneumonia</b></i></mark><i> , and </i><mark class=\"hl lab\"><i><b>Pneumothorax</b></i></mark><i> !)</i></p><nav class=\"un\"><button class=\"nv\" data-u=\"u113\">← Case 2</button><button class=\"nv\" data-u=\"u115\">Case 4 →</button></nav></article><article class=\"view unit\" id=\"u115\" hidden style=\"--c:#00897b\"><button class=\"back\" data-p=\"6\">← Pediatrics</button><header class=\"uh\"><span class=\"ul\">Case 4</span><h1>Acute Bronchiolitis</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Bronchiolitis\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Acute viral lower respiratory tract inflammation of the small bronchioles in <b>infants and children &lt; 2 years old</b> (peak <b>2–6 months</b>).</p><h3><b>2. Etiology (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>RSV</b> (Respiratory Syncytial Virus — <b>#1 cause, ~70–80%</b>; winter epidemics!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Other Viruses:</b> Human Metapneumovirus, Parainfluenza, Rhinovirus, Influenza, Adenovirus.</span></p><h3><b>3. Pathophysiology &amp; Clinical Picture</b></h3><p>Bronchiolar epithelial necrosis -&gt; submucosal edema + thick mucus plugs -&gt; small airway obstruction -&gt; air trapping and patchy atelectasis.</p>\n<ul>\n<li class=\"l1\">Starts with <b>2–3 days of viral URTI</b> (rhinorrhea, low-grade fever), progressing to <b>tachypnea</b>, <b>paroxysmal cough</b>, <b>diffuse wheezing AND fine inspiratory crackles</b>, nasal flaring, subcostal retractions, poor feeding!</li>\n<li class=\"l1\"><b>Apnea Alert:</b> Young infants (<b>&lt; 1–2 months</b> or preterm) may present with <b>apnea</b> as the primary symptom!</li>\n</ul><h3><b>4. Investigations</b></h3><ul>\n<li class=\"l1\"><b>STRICTLY A CLINICAL DIAGNOSIS!</b></li>\n<li class=\"l1\">Routine <mark class=\"hl mech\"><b>CXR, viral PCR, and CBC are NOT recommended</b></mark> in typical mild-moderate bronchiolitis! (CXR shows hyperinflation + patchy atelectasis, often mistakenly called \"pneumonia\" leading to unnecessary antibiotics!). Check <mark class=\"hl mech\"><b>Pulse Oximetry (SpO2)</b></mark> continuously if admitted.</li>\n</ul><h3><b>5. Treatment (Supportive Care ONLY — Less Is More!)</b></h3><ul>\n<li class=\"l1\"><b>Hospitalization Criteria:</b> Age &lt; 2–3 months (apnea risk), <mark class=\"hl mech\"><b>SpO2 &lt; 90–92%</b></mark> , moderate-severe distress (RR &gt; 60–70, grunting), dehydration / inability to feed!</li>\n<li class=\"l1\"><b>Core Management:</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Gentle Nasal Suctioning</b> (crucial before feeds — infants are obligate nasal breathers!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Hydration:</b> Frequent small oral feeds, or <mark class=\"hl rx\"><b>NG/IV fluids</b></mark> if unable to feed safely.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Oxygen:</b> Nasal cannula / <b>HFNC</b> (High-Flow Nasal Cannula) if <mark class=\"hl mech\"><b>SpO2 &lt; 90–92%</b></mark> .</span></p>\n<ul>\n<li class=\"l1\"><b>WHAT NOT TO DO (AAP Guidelines — Proven Ineffective!):</b></li>\n<li class=\"l2\"><b>NO routine Bronchodilators</b> (Salbutamol/Albuterol does NOT work in true bronchiolitis!).</li>\n<li class=\"l2\"><mark class=\"hl rx\"><b>NO Corticosteroids</b></mark> (systemic or inhaled).</li>\n<li class=\"l2\"><b>NO Antibiotics</b> (unless confirmed secondary bacterial infection/acute otitis media).</li>\n<li class=\"l2\"><b>NO Chest Physiotherapy.</b></li>\n<li class=\"l1\"><b>Prevention:</b> <b>Nirsevimab</b> (long-acting monoclonal antibody) or <b>Palivizumab</b> for high-risk premature/CHD infants; maternal RSV vaccine.</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u114\">← Case 3</button><button class=\"nv\" data-u=\"u116\">Case 5 →</button></nav></article><article class=\"view unit\" id=\"u116\" hidden style=\"--c:#00897b\"><button class=\"back\" data-p=\"6\">← Pediatrics</button><header class=\"uh\"><span class=\"ul\">Case 5</span><h1>Croup (LARYNGOTRACHEOBRONCHITIS) vs. Acute Epiglottitis</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Croup+%28LARYNGOTRACHEOBRONCHITIS%29+vs.+Acute+Epiglottitis\">🔍 Search on Google</a></header><h3><b>1. Definitions &amp; Comparison</b></h3><table class=\"t \"><tr class=\"hd\"><th><p><b>Feature</b></p></th><th><p><b>Croup </b><i><b>(Common Daily Case!)</b></i></p></th><th><p><b>Acute Epiglottitis </b><i><b>(Life-Threatening Emergency!)</b></i></p></th></tr><tr><td><p><b>Age</b></p></td><td><p><b>6 months – 3 years</b></p></td><td><p>Any age (historically 2–7 yrs; now rare due to <b>Hib vaccine</b>)</p></td></tr><tr><td><p><b>Etiology</b></p></td><td><p><b>Parainfluenza Virus</b> (#1)</p></td><td><p><i><b>Haemophilus influenzae</b></i><b> type b (Hib)</b>, <i>S. pyogenes</i>, <i>S. aureus</i></p></td></tr><tr><td><p><b>Onset</b></p></td><td><p>Gradual (after 1–2 days URTI coryza)</p></td><td><p><b>Abrupt, rapid progression over hours!</b></p></td></tr><tr><td><p><b>Classic Triad / Signs</b></p></td><td><p><b>\"Barking\" (seal-like) cough</b> + <b>Hoarseness</b> + <b>Inspiratory Stridor</b> (worse at night/crying!) + low-grade fever</p></td><td><p><b>\"4 Ds\": Drooling, Dysphagia, Dysphonia (muffled voice), Distress</b> + <b>High Fever</b>, toxic, <b>Tripod Position</b> (NO barking cough!)</p></td></tr><tr><td><p><b>Neck X-Ray</b></p></td><td><p><b>\"Steeple Sign\"</b> (subglottic narrowing — <i>diagnosis is clinical; X-ray NOT needed!</i>)</p></td><td><p><b>\"Thumbprint Sign\"</b> (swollen epiglottis — <i>NEVER send unstable child to X-ray!</i>)</p></td></tr></table><h3><b>2. Treatment</b></h3><ul>\n<li class=\"l1\"><b>Croup:</b></li>\n<li class=\"l2\"><mark class=\"hl lab\"><b>ALL Severities (Even Mild!):</b></mark> <mark class=\"hl rx\"><b>Single Dose Oral Dexamethasone 0.6 mg/kg</b></mark> (max 10–16 mg) — OR nebulized Budesonide 2 mg! <i>(Keep child calm — crying worsens stridor!)</i></li>\n<li class=\"l2\"><b>Moderate-Severe (Stridor at rest / Retractions):</b> Add <mark class=\"hl rx\"><b>Nebulized Racemic Epinephrine</b></mark> (or L-Epinephrine 1:1,000, 0.5 mL/kg up to 5 mL) -&gt; <b>Observe at least 3– 4 hours</b> after epinephrine for rebound stridor!</li>\n<li class=\"l1\"><b>Acute Epiglottitis (AIRWAY EMERGENCY!):</b></li>\n<li class=\"l2\"><b>DO NOT agitate the child, DO NOT lay flat, and DO NOT inspect throat with a tongue depressor!</b> (Can trigger complete fatal laryngospasm!).</li>\n<li class=\"l2\"><b>Immediate ENT/Anesthesia call for Controlled Endotracheal Intubation in OR</b> -&gt; then start <mark class=\"hl rx\"><b>IV Ceftriaxone</b></mark> (+ Vancomycin)!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u115\">← Case 4</button><button class=\"nv\" data-u=\"u117\">Case 6 →</button></nav></article><article class=\"view unit\" id=\"u117\" hidden style=\"--c:#00897b\"><button class=\"back\" data-p=\"6\">← Pediatrics</button><header class=\"uh\"><span class=\"ul\">Case 6</span><h1>Pediatric Community-Acquired Pneumonia (CAP)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pediatric+Community-Acquired+Pneumonia+%28CAP%29\">🔍 Search on Google</a></header><h3><b>1. Etiology (Separated by Age — CRUCIAL FOR ANTIBIOTIC CHOICE!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Neonates (&lt; 1 Month):</b> <mark class=\"hl lab\"><b>GBS</b></mark> , <i>E. coli</i>, <i>Listeria</i> (treat with IV Ampicillin + Gentamicin/Cefotaxime).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>1 – 3 Months:</b> <i>Chlamydia trachomatis</i> (afebrile, <b>\"staccato\" cough</b>, eosinophilia, history of neonatal conjunctivitis!), Viruses (<b>RSV</b>), <i>S. pneumoniae</i>, <i>S. aureus</i>.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>3 Months – 5 Years:</b> <b>Viruses (#1 overall!)</b>; <b>Bacteria:</b> <i><b>Streptococcus pneumoniae</b></i> (#1 bacterial!), <i>H. influenzae</i>, <i>S. aureus</i>.</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>≥ 5 Years &amp; Adolescents:</b> <i><b>Mycoplasma pneumoniae</b></i> (#1 atypical!), <i>S. pneumoniae</i>, <i>Chlamydophila pneumoniae</i>.</span></p><h3><b>2. Clinical Picture &amp; WHO Age-Specific Tachypnea Thresholds</b></h3><ul>\n<li class=\"l1\">Fever, cough, <b>tachypnea</b> (most sensitive clinical sign of pediatric pneumonia!), nasal flaring, retractions, grunting, abdominal pain (lower lobe pneumonia irritating diaphragm!), decreased breath sounds/crackles.</li>\n<li class=\"l1\"><b>WHO Tachypnea Cutoffs:</b> &lt; 2 months: <b>≥ 60/min</b> | 2–12 months: <b>≥ 50/min</b> | 1–5 years: <b>≥ 40/min</b> | &gt; 5 years: <b>≥ 20–30/min</b>.</li>\n</ul><h3><b>3. Investigations &amp; Treatment</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Outpatient Mild CAP:</b></mark> Diagnosis is <b>clinical</b> (CXR NOT required unless failing therapy, severe, or hospitalized!).</li>\n<li class=\"l1\"><b>Inpatient / Severe:</b> <mark class=\"hl mech\"><b>CXR</b></mark> , Pulse Oximetry, <mark class=\"hl mech\"><b>CBC</b></mark> , <b>Blood Culture</b> (in hospitalized).</li>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Empirical Antibiotics (When Bacterial CAP Suspected):</b></mark></li>\n<li class=\"l2\"><i>Outpatient (&lt; 5 yrs — Typical Bacterial):</i> <mark class=\"hl rx\"><b>High-Dose Oral Amoxicillin (90 mg/kg/day divided BID)</b></mark> for 5–7 days!</li>\n<li class=\"l2\"><i>Outpatient (≥ 5 yrs — If Atypical Suspected):</i> <mark class=\"hl rx\"><b>Oral Azithromycin</b></mark> (10 mg/kg Day 1, then 5 mg/kg Days 2–5) +/- Amoxicillin.</li>\n<li class=\"l2\"><i>Inpatient (Fully Immunized):</i> <mark class=\"hl rx\"><b>IV Ampicillin</b></mark> or <mark class=\"hl rx\"><b>IV Ceftriaxone</b></mark> ; add <mark class=\"hl rx\"><b>Azithromycin</b></mark> if atypical; add <mark class=\"hl rx\"><b>Vancomycin/Clindamycin</b></mark> if <b>MRSA / Empyema / Necrotizing </b>suspected!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u116\">← Case 5</button><button class=\"nv\" data-u=\"u118\">Case 7 →</button></nav></article><article class=\"view unit\" id=\"u118\" hidden style=\"--c:#00897b\"><button class=\"back\" data-p=\"6\">← Pediatrics</button><header class=\"uh\"><span class=\"ul\">Case 7</span><h1>Pediatric Bronchial Asthma</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pediatric+Bronchial+Asthma\">🔍 Search on Google</a></header><h3><b>1. Clinical Clues &amp; Diagnostic Challenge (&lt; 5 Years)</b></h3><ul>\n<li class=\"l1\">Recurrent wheezing, night/early morning cough, exercise/laughing/crying-induced cough, personal/family <b>atopy</b> (<b>Asthma Predictive Index</b>).</li>\n<li class=\"l1\"><i>Caveat:</i> <mark class=\"hl mech\"><b>Spirometry cannot be performed reliably in children &lt; 5 years</b></mark> -&gt; diagnosis in &lt; 5 yrs is clinical (trial of low-dose <b>ICS</b> for 2–3 months showing improvement, and worsening when stopped!).</li>\n</ul><h3><b>2. Acute Exacerbation Treatment (Pediatric ER)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Oxygen:</b> Maintain <mark class=\"hl mech\"><b>SpO2 ≥ 94%</b></mark> .</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>SABA:</b> <mark class=\"hl rx\"><b>Nebulized Salbutamol</b></mark> (or <b>MDI + Spacer</b> 4–8 puffs!) every 20 min × 3 doses (<b>0.15 mg/kg/dose</b>, min 2.5 mg, max 5 mg; or weight-based: &lt; 20 kg = 2.5 mg, ≥ 20 kg = 5 mg).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Add Ipratropium Bromide (250–500 mcg)</b> to first 3 nebulizations in moderate-severe attacks!</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Systemic Corticosteroid EARLY:</b> <mark class=\"hl rx\"><b>Oral Prednisolone 1–2 mg/kg/day</b></mark> (max 40–50 mg) for 3–5 days, OR <mark class=\"hl rx\"><b>Oral Dexamethasone 0.6 mg/kg</b></mark> (single/2-day dose), OR <mark class=\"hl rx\"><b>IV Methylprednisolone</b></mark> if unable to tolerate PO.</span></p>\n<p class=\"num\"><span class=\"n\">5.</span><span class=\"nt\"><b>Severe Refractory:</b> <mark class=\"hl rx\"><b>IV Magnesium Sulfate (40–50 mg/kg, max 2 g)</b></mark> over 20 min.</span></p><h3><b>3. Chronic Controller Therapy (GINA Pediatric)</b></h3><ul>\n<li class=\"l1\"><b>Daily Low-Dose ICS</b> via <b>MDI + Valved Holding Chamber (Spacer) + Facemask</b> (in &lt; 4–5 yrs; mouthpiece if ≥ 5 yrs) OR <b>ICS-Formoterol</b> (MART for ≥ 6–12 yrs). Always rinse mouth after ICS to prevent oral candidiasis!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u117\">← Case 6</button><button class=\"nv\" data-u=\"u119\">Case 8 →</button></nav></article><article class=\"view unit\" id=\"u119\" hidden style=\"--c:#00897b\"><button class=\"back\" data-p=\"6\">← Pediatrics</button><header class=\"uh\"><span class=\"ul\">Case 8</span><h1>Foreign Body Aspiration (FBA)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Foreign+Body+Aspiration+%28FBA%29\">🔍 Search on Google</a></header><h3><b>1. Definition &amp; Epidemiology</b></h3><p>Inhalation of a solid/semi-solid object (classic in Egypt: <b>peanuts, watermelon/sunflower seeds [</b><i><b>Leb</b></i><b>], coins, small toy parts</b>) into the larynx, trachea, or bronchi. Peak age: <b>6 months – 3 years</b>.</p><h3><b>2. Clinical Picture</b></h3><ul>\n<li class=\"l1\"><b>Classic History:</b> Sudden onset of <b>choking, gagging, and coughing</b> while eating or playing with small objects <i>(note: initial choking episode may be unwitnessed, presenting days later as persistent unilateral wheeze or recurrent pneumonia!)</i>.</li>\n<li class=\"l1\"><b>Laryngeal/Tracheal FB:</b> Biphasic/inspiratory stridor, hoarseness, severe respiratory distress (<b>EMERGENCY!</b>).</li>\n<li class=\"l1\"><b>Bronchial FB (More common in Right Main Bronchus):</b> <b>Unilateral wheezing</b>, <b>asymmetrical/decreased breath sounds</b> on one side!</li>\n</ul><h3><b>3. Investigations &amp; Treatment</b></h3><ul>\n<li class=\"l1\"><b>Chest X-Ray (Inspiratory + Expiratory views, or Bilateral Decubitus in infants):</b></li>\n<li class=\"l2\">Most aspirated objects (peanuts/seeds) are <b>RADIOLUCENT (invisible on X-ray!)</b>.</li>\n<li class=\"l2\">Look for <b>indirect ball-valve signs:</b> <b>Unilateral hyperinflation (air trapping)</b> on expiratory film, mediastinal shift away from affected side, or focal atelectasis! <i>(Normal CXR does NOT exclude FBA!)</i></li>\n<li class=\"l1\"><b>Emergency First Aid (If Complete Choking/Cannot Cough or Cry):</b></li>\n<li class=\"l2\"><b>&lt; 1 Year:</b> <b>5 Back Blows + 5 Chest Thrusts</b> (NO abdominal thrusts in infants!).</li>\n<li class=\"l2\"><b>≥ 1 Year:</b> <b>Abdominal Thrusts (Heimlich Maneuver)</b>.</li>\n<li class=\"l1\"><b>Definitive Treatment:</b> <mark class=\"hl rx\"><b>Rigid Bronchoscopy</b></mark> (Diagnostic &amp; Therapeutic Gold Standard!) -&gt; <b>Do NOT perform blind finger sweeps</b>!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u118\">← Case 7</button><button class=\"nv\" data-u=\"u120\">Case 9 →</button></nav></article><article class=\"view unit\" id=\"u120\" hidden style=\"--c:#00897b\"><button class=\"back\" data-p=\"6\">← Pediatrics</button><header class=\"uh\"><span class=\"ul\">Case 9</span><h1>Acute Pediatric Gastroenteritis &amp; Dehydration (WHO / IMCI PROTOCOL)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Pediatric+Gastroenteritis+%26+Dehydration+%28WHO+%2F+IMCI+PROTOCOL%29\">🔍 Search on Google</a></header><h3><b>1. Etiology (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Viral (~70–80%):</b> <b>Rotavirus</b> (#1 cause of severe dehydrating diarrhea in infants &lt; 2 yrs — preventable by vaccine!), Norovirus, Adenovirus.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Bacterial:</b> <i>E. coli</i>, <i>Salmonella</i>, <i>Shigella</i>, <i>Campylobacter</i>.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Parasitic (Common in Egypt):</b> <i>Giardia lamblia</i>, <i>Entamoeba histolytica</i>, <i>Cryptosporidium</i>.</span></p><h3><b>2. Dehydration Assessment (WHO / IMCI 3-Tier Classification)</b></h3><table class=\"t \"><tr><td><p><b>Clinical Sign</b></p></td><td><p><b>NO Dehydration </b><i><b>(&lt; 5% loss)</b></i></p></td><td><p><b>SOME (Moderate) Dehydration </b><i><b>(5–10% loss)</b></i></p></td><td><p><b>SEVERE Dehydration </b><i><b>(&gt; 10% loss)</b></i></p></td></tr><tr><td><p><b>General Condition</b></p></td><td><p>Well, alert</p></td><td><p><b>Restless, irritable</b></p></td><td><p><b>Lethargic or unconscious</b></p></td></tr><tr><td><p><b>Eyes</b></p></td><td><p>Normal</p></td><td><p><b>Sunken</b></p></td><td><p><b>Very sunken</b></p></td></tr><tr><td><p><b>Thirst</b></p></td><td><p>Drinks normally, not thirsty</p></td><td><p><b>Thirsty, drinks eagerly</b></p></td><td><p><b>Drinks poorly / Unable to drink</b></p></td></tr><tr><td><p><b>Skin Pinch (Abdomen)</b></p></td><td><p>Goes back immediately</p></td><td><p><b>Goes back slowly</b> (1–2 sec)</p></td><td><p><b>Goes back VERY slowly (&gt; 2 sec)</b></p></td></tr><tr><td></td><td></td><td></td><td></td></tr><tr><td><p><b>Perfusion / Urine</b></p></td><td><p>Normal tears &amp; urine</p></td><td><p>Reduced tears, decreased wet diapers</p></td><td><p><b>Absent tears, anuria, tachycardia, weak/absent pulse, CRT &gt; 3 sec!</b></p></td></tr></table><h3><b>3. Treatment (WHO Plans A, B, C + Zinc!)</b></h3><ul>\n<li class=\"l1\"><b>Plan A (NO Dehydration — Home Management):</b> Continue breastfeeding/age-appropriate feeding + give <b>Low-Osmolarity ORS</b> after each loose stool (&lt; 2 yrs: 50– 100 mL; ≥ 2 yrs: 100–200 mL).</li>\n<li class=\"l1\"><b>Plan B (SOME Dehydration — Oral Rehydration Therapy):</b> Give <b>ORS 75 mL/kg over 4 hours</b> (frequent small sips/spoonfuls every 1–2 min if vomiting; <b>Ondansetron </b>0.15 mg/kg single oral/IV dose helps stop vomiting so ORS succeeds!); reassess at 4 hours.</li>\n<li class=\"l1\"><b>Plan C (SEVERE Dehydration / Shock — IV Emergency!):</b></li>\n<li class=\"l2\"><b>Immediate Bolus:</b> <b>20 mL/kg IV 0.9% Normal Saline or Ringer’s Lactate</b> over 15–30 min (repeat up to 2–3× if still in shock!).</li>\n<li class=\"l2\"><b>WHO IV Deficit Replacement (100 mL/kg):</b> &lt; 12 months: 30 mL/kg over 1 hr, then 70 mL/kg over 5 hrs | ≥ 12 months: 30 mL/kg over 30 min, then 70 mL/kg over 2.5 hrs.</li>\n<li class=\"l1\"><mark class=\"hl lab\"><b>MANDATORY ADJUNCT IN ALL CHILDREN:</b></mark> <b>Oral Zinc Sulfate</b> for <b>10–14 days</b> (&lt; 6 months: <b>10 mg/day</b>; ≥ 6 months: <b>20 mg/day</b>) — reduces duration, severity, and recurrence for 3 months!</li>\n<li class=\"l1\"><i>AVOID:</i> <b>Loperamide / Diphenoxylate</b> (CONTRAINDICATED in children due to ileus/respiratory depression!). Avoid routine antibiotics unless <b>bloody dysentery </b>(<i>Shigella</i> -&gt; Azithromycin/Ceftriaxone), Cholera, or <i>Giardia/Entamoeba</i> (Metronidazole)!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u119\">← Case 8</button><button class=\"nv\" data-u=\"u121\">Case 10 →</button></nav></article><article class=\"view unit\" id=\"u121\" hidden style=\"--c:#00897b\"><button class=\"back\" data-p=\"6\">← Pediatrics</button><header class=\"uh\"><span class=\"ul\">Case 10</span><h1>Infantile Hypertrophic Pyloric Stenosis</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Infantile+Hypertrophic+Pyloric+Stenosis\">🔍 Search on Google</a></header><h3><b>1. Definition &amp; Epidemiology</b></h3><p>Idiopathic hypertrophy of the pyloric circular muscle causing gastric outlet obstruction; classic in <b>first-born male infants</b> (4:1 M:F) aged <b>2 – 6 weeks</b> (rarely &gt; 3 months). <i>(Associated with early </i><i><b>Erythromycin</b></i><i> exposure!).</i></p><h3><b>2. Clinical Picture</b></h3><ul>\n<li class=\"l1\"><b>Non-bilious, forceful \"projectile\" vomiting</b> immediately after every feed -&gt; infant remains <b>\"hungry and eager to feed\"</b> right after vomiting!</li>\n<li class=\"l1\">Weight loss / dehydration / constipation.</li>\n<li class=\"l1\"><b>Pathognomonic Exam:</b> Palpable <b>firm, mobile \"olive-shaped\" mass</b> in the <b>epigastrium/RUQ</b> (best felt after vomiting or during feeding) + visible gastric peristaltic waves moving left-to-right!</li>\n</ul><h3><b>3. Investigations &amp; Electrolyte Classic</b></h3><ul>\n<li class=\"l1\"><b>Classic Lab Abnormality:</b> <b>Hypochloremic, Hypokalemic Metabolic Alkalosis</b> (from losing gastric HCl + renal H+/K+ wasting to preserve volume — \"paradoxical aciduria\")!</li>\n<li class=\"l1\"><b>Diagnostic Gold Standard:</b> <b>Abdominal Ultrasound</b> (pyloric muscle thickness <b>≥ 3–4 mm</b> and channel length <b>≥ 14–16 mm</b>).</li>\n</ul><h3><b>4. Treatment (NEVER RUSH TO SURGERY BEFORE FIXING ELECTROLYTES!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>FIRST:</b> <b>NPO</b> + <b>IV Fluid &amp; Electrolyte Resuscitation</b> (0.9% or 0.45% Saline with KCl once urinating) until <b>alkalosis, hypokalemia, and dehydration are completely corrected</b> (prevents fatal post-anesthesia apnea!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Definitive Surgery:</b> <b>Ramstedt Pyloromyotomy</b> (laparoscopic/open longitudinal splitting of hypertrophied muscle).</span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u120\">← Case 9</button><button class=\"nv\" data-u=\"u122\">Case 11 →</button></nav></article><article class=\"view unit\" id=\"u122\" hidden style=\"--c:#00897b\"><button class=\"back\" data-p=\"6\">← Pediatrics</button><header class=\"uh\"><span class=\"ul\">Case 11</span><h1>Intussusception</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Intussusception\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Telescoping of a proximal bowel segment into an adjacent distal segment (most commonly <b>ileocolic</b> — terminal ileum into cecum). <b>#1 cause of intestinal obstruction in children aged 6 – 36 months (peak 6–18 months)!</b></p><h3><b>2. Etiology (Separated by Age)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Infants/Toddlers (6–36 Months — ~90% Idiopathic):</b> Hypertrophied <b>Peyer’s patches</b> following a viral URTI/gastroenteritis (e.g., Adenovirus) acting as a lead point.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Older Children (&gt; 3–5 Years — Look for a Pathologic Lead Point!):</b> <b>Meckel’s diverticulum</b>, <mark class=\"hl lab\"><b>HSP</b></mark> (Henoch-Schönlein Purpura — submucosal hematoma!), Intestinal polyps, Lymphoma.</span></p><h3><b>3. Clinical Picture (Classic Triad — Present Together in &lt; 30% Early!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Sudden intermittent, severe colicky abdominal pain</b> (every 15–20 min; baby screams and <b>draws knees up to chest</b>, appearing completely normal/lethargic between episodes!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\">Vomiting (initially undigested, later <b>bilious</b>!).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>\"Currant Jelly\" Stools</b> (dark red blood + mucus from bowel ischemia — <b>LATE SIGN!</b> Do NOT wait for this!).</span></p>\n<ul>\n<li class=\"l1\"><b>Exam:</b> Palpable <b>\"sausage-shaped\" mass</b> in <b>RUQ</b> with an empty RLQ (<b>Dance’s sign</b>).</li>\n</ul><h3><b>4. Investigations &amp; Treatment</b></h3><ul>\n<li class=\"l1\"><b>Diagnostic Gold Standard:</b> <b>Abdominal Ultrasound</b> -&gt; <b>\"Target / Doughnut Sign\"</b> (transverse view) or \"Pseudokidney sign\"!</li>\n<li class=\"l1\"><b>Treatment:</b></li>\n<li class=\"l2\"><i>Immediate:</i> <b>NPO</b>, IV fluids, <b>NG tube</b> decompression.</li>\n<li class=\"l2\"><i>If Stable &amp; NO Peritonitis/Perforation:</i> <b>Non-Surgical Pneumatic (Air) or Hydrostatic (Saline) Enema Reduction</b> under ultrasound/fluoroscopic guidance (both diagnostic &amp; curative in ~85%!).</li>\n<li class=\"l2\"><i>If Peritonitis, Perforation, Shock, or Failed Enema:</i> <b>Emergent Surgical Reduction</b> (+/- bowel resection).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u121\">← Case 10</button><button class=\"nv\" data-u=\"u123\">Case 12 →</button></nav></article><article class=\"view unit\" id=\"u123\" hidden style=\"--c:#00897b\"><button class=\"back\" data-p=\"6\">← Pediatrics</button><header class=\"uh\"><span class=\"ul\">Case 12</span><h1>Malrotation with Midgut Volvulus &amp; Hirschsprung Disease</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Malrotation+with+Midgut+Volvulus+%26+Hirschsprung+Disease\">🔍 Search on Google</a></header><p class=\"muted\"><i>(Two Critical Neonatal Intestinal Emergencies Every Doctor Must Spot Immediately!)</i></p><h3><b>A. Malrotation with Midgut Volvulus (TRUE SURGICAL EMERGENCY!)</b></h3><ul>\n<li class=\"l1\"><b>Key Red Flag:</b> <b>BILIOUS (DARK GREEN) VOMITING in a Neonate/Infant</b> = <b>Malrotation with Midgut Volvulus until proven otherwise!</b></li>\n<li class=\"l1\"><b>Pathology:</b> Incomplete embryonic gut rotation leaves a narrow mesenteric base -&gt; entire midgut twists around <b>Superior Mesenteric Artery</b> -&gt; catastrophic bowel necrosis within hours!</li>\n<li class=\"l1\"><b>Diagnosis:</b> <b>Upper GI Contrast Series</b> (Gold Standard in stable infant -&gt; <b>\"Corkscrew Sign\"</b> of twisted duodenum / duodenojejunal junction fails to cross midline). <i>(Plain X-ray may show </i><i><b>\"Double-Bubble\"</b></i><i> sign or be deceptively normal!)</i></li>\n<li class=\"l1\"><b>Treatment:</b> <b>Emergent Laparotomy (Ladd’s Procedure)</b> — <i>do not delay!</i></li>\n</ul><h3><b>B. Hirschsprung Disease (Congenital Aganglionic Megacolon)</b></h3><ul>\n<li class=\"l1\"><b>Pathology:</b> Failure of neural crest cells to migrate distally -&gt; absence of ganglion cells (Meissner’s &amp; Auerbach’s plexuses) in distal rectum/rectosigmoid -&gt; tonic contraction -&gt; functional obstruction. <i>(Strongly associated with </i><i><b>Down Syndrome</b></i><i>!).</i></li>\n<li class=\"l1\"><b>Key Red Flag:</b> <b>Failure to pass Meconium within the FIRST 48 Hours of Life</b> (in a term infant!), chronic severe constipation from birth, abdominal distension, bilious vomiting.</li>\n<li class=\"l1\"><b>Exam Clue:</b> Digital Rectal Exam shows <b>tight empty rectum</b> followed by an <b>explosive gush of foul-smelling gas &amp; liquid stool</b> (<b>\"Blast Sign\"</b>)!</li>\n<li class=\"l1\"><b>Diagnosis:</b> Contrast Enema (<b>transition zone</b> narrowed rectum -&gt; dilated proximal colon) -&gt; <b>Gold Standard = Full-Thickness Rectal Suction Biopsy</b> (absent ganglion cells!).</li>\n<li class=\"l1\"><b>Treatment:</b> Surgical resection of aganglionic segment (<b>Pull-through procedure</b>). <i>(Watch for life-threatening </i><i><b>Hirschsprung-Associated Enterocolitis</b></i><i>: explosive diarrhea + fever + toxic shock -&gt; IV fluids, broad-spectrum antibiotics, rectal washouts!)</i></li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u122\">← Case 11</button><button class=\"nv\" data-u=\"u124\">Case 13 →</button></nav></article><article class=\"view unit\" id=\"u124\" hidden style=\"--c:#00897b\"><button class=\"back\" data-p=\"6\">← Pediatrics</button><header class=\"uh\"><span class=\"ul\">Case 13</span><h1>Infantile Gastroesophageal Reflux (GER) vs. Cmpa</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Infantile+Gastroesophageal+Reflux+%28GER%29+vs.+Cmpa\">🔍 Search on Google</a></header><h3><b>1. Normal Infantile GER (\"Happy Spitter\") vs. GERD</b></h3><ul>\n<li class=\"l1\"><b>Physiologic GER:</b> Effortless spitting up/regurgitation after feeds in a <b>thriving, happy, gaining-weight infant</b> (peaks at 4 months, resolves by 12–18 months!).</li>\n<li class=\"l2\"><i>Management:</i> <b>Reassurance ONLY!</b> Small frequent feeds, burping, keep upright 20–30 min after feeds (still <b>sleep SUPINE on back</b> to prevent SIDS!). <mark class=\"hl rx\"><b>NO PPIs/Ranitidine needed!</b></mark></li>\n<li class=\"l1\"><mark class=\"hl lab\"><b>GERD (Pathologic):</b></mark> Reflux causing <b>poor weight gain/FTT</b>, esophagitis (arching back during feeds — <b>Sandifer Syndrome</b>), hematemesis, or recurrent apnea/aspiration.</li>\n</ul><h3><b>2. Cow’s Milk Protein Allergy (CMPA) — </b><b>Very Common in Egyptian Infants!</b></h3><ul>\n<li class=\"l1\"><b>Definition:</b> Immune reaction (IgE-mediated or Non-IgE-mediated) to cow’s milk proteins (casein/whey), occurring even in <b>exclusively breastfed</b> infants via maternal dairy intake!</li>\n<li class=\"l1\"><b>Clinical Picture:</b></li>\n<li class=\"l2\"><i>Non-IgE (Most Common):</i> <b>Blood-streaked mucoid stools</b> (allergic proctocolitis) in an otherwise healthy infant, colic/irritability, vomiting, eczema, poor weight gain.</li>\n<li class=\"l2\"><i>IgE-Mediated:</i> Rapid urticaria, angioedema, wheezing, vomiting within minutes–2 hrs of formula.</li>\n<li class=\"l1\"><b>Treatment:</b></li>\n<li class=\"l2\"><i>If Breastfed:</i> <mark class=\"hl lab\"><b>Strict maternal elimination of ALL cow’s milk/dairy products</b></mark> for 2–4 weeks (supplement mother with Calcium + Vitamin D!).</li>\n<li class=\"l2\"><i>If Formula-Fed:</i> Switch to <b>Extensively Hydrolyzed Formula (eHF)</b> (or <b>Amino Acid Formula</b> if severe/anaphylaxis/FTT!). <i>(Avoid Soy formula in &lt; 6 months due to cross-reactivity!).</i></li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u123\">← Case 12</button><button class=\"nv\" data-u=\"u125\">Case 14 →</button></nav></article><article class=\"view unit\" id=\"u125\" hidden style=\"--c:#00897b\"><button class=\"back\" data-p=\"6\">← Pediatrics</button><header class=\"uh\"><span class=\"ul\">Case 14</span><h1>Nutritional Rickets &amp; Pediatric Iron Deficiency Anemia (IDA)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Nutritional+Rickets+%26+Pediatric+Iron+Deficiency+Anemia+%28IDA%29\">🔍 Search on Google</a></header><h3><b>A. Nutritional Rickets (Vitamin D Deficiency)</b></h3><ul>\n<li class=\"l1\"><b>Definition:</b> Defective mineralization of growing <b>epiphyseal growth plates</b> (before fusion) and osteoid matrix in infants/children (typically 6–24 months; common in exclusively breastfed infants without Vit D drops or inadequate sun exposure!).</li>\n<li class=\"l1\"><b>Clinical Signs (Head-to-Toe):</b></li>\n<li class=\"l2\"><i>Skull:</i> <b>Craniotabes</b> (\"ping-pong ball\" soft occipital/parietal skull), <b>Frontal bossing</b>, delayed closure of anterior fontanelle, delayed dentition.</li>\n<li class=\"l2\"><i>Chest:</i> <b>Rachitic Rosary</b> (beaded costochondral junctions), <b>Harrison’s sulcus</b> (groove along lower ribs).</li>\n<li class=\"l2\"><i>Limbs:</i> <b>Widened wrists &amp; ankles</b>, <b>Genu Varum (bowlegs)</b> or Genu Valgum, hypotonia, <b>hypocalcemic tetany / seizures</b>!</li>\n<li class=\"l1\"><b>Labs &amp; X-Ray:</b> <b>Low 25-OH Vitamin D</b>, <mark class=\"hl mech\"><b>Markedly Elevated ALP</b></mark> (Alkaline Phosphatase — earliest &amp; best screening marker!), <b>Low Serum Phosphate</b> (PTH causes renal phosphate wasting!), Normal or Low Calcium, <b>High PTH</b>.</li>\n<li class=\"l2\"><i>Wrist X-Ray:</i> <b>Cupping, Fraying, and Splaying</b> of distal radial/ulnar metaphyses + widened growth plate!</li>\n<li class=\"l1\"><b>Treatment:</b> <b>Vitamin D3 (Cholecalciferol)</b> 2,000 IU/day (or 50,000 IU weekly) for 8–12 weeks + adequate dietary <mark class=\"hl rx\"><b>Calcium</b></mark> (500 mg/day) -&gt; then maintenance <b>400– 600 IU/day</b>. <i>(Prevention: Give </i><mark class=\"hl lab\"><i><b>ALL breastfed infants 400 IU/day Vitamin D</b></i></mark><i> starting in the first days of life!)</i></li>\n</ul><h3><b>B. Pediatric Iron Deficiency Anemia (IDA)</b></h3><ul>\n<li class=\"l1\"><b>Classic Egyptian Scenario:</b> <b>9–24 month old toddler</b> drinking excessive <b>unmodified cow’s milk (&gt; 700 mL/day)</b> or prolonged exclusive breastfeeding &gt; 6 months without iron-rich complementary foods!</li>\n<li class=\"l1\"><b>Labs:</b> Low Hb, Low MCV, High RDW, Low Ferritin.</li>\n<li class=\"l1\"><b>Treatment:</b> <b>Elemental Iron 3–6 mg/kg/day</b> (Ferrous sulfate/bisglycinate) given between meals with Vitamin C (continue 2–3 months after Hb normalizes!) + limit cow’s milk to &lt; 500 mL/day (avoid whole cow’s milk entirely before <b>12 months</b>!).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u124\">← Case 13</button><button class=\"nv\" data-u=\"u126\">Case 15 →</button></nav></article><article class=\"view unit\" id=\"u126\" hidden style=\"--c:#00897b\"><button class=\"back\" data-p=\"6\">← Pediatrics</button><header class=\"uh\"><span class=\"ul\">Case 15</span><h1>Failure to Thrive (FTT) &amp; Severe Acute Malnutrition</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Failure+to+Thrive+%28FTT%29+%26+Severe+Acute+Malnutrition\">🔍 Search on Google</a></header><h3><b>1. Failure to Thrive (FTT)</b></h3><ul>\n<li class=\"l1\"><b>Definition:</b> Weight-for-age <b>&lt; 3rd–5th percentile</b>, OR weight crossing <b>≥ 2 major percentile lines downward</b>, OR weight-for-height &lt; 5th percentile.</li>\n<li class=\"l1\"><b>Etiology (Separated):</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Inadequate Caloric Intake (~80% — Most Common!):</b> Poor breastfeeding technique, dilute formula mixing, poverty/neglect, feeding difficulties (cleft palate, cerebral palsy).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Malabsorption:</b> <b>Celiac Disease</b> (classic onset 6–24 mos after introducing wheat/gluten -&gt; chronic diarrhea, abdominal distension, irritability, muscle wasting!), <b>Cystic Fibrosis</b>, CMPA.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Increased Metabolic Demand:</b> Congenital Heart Disease, Hyperthyroidism, Chronic infections (TB/HIV), Renal Tubular Acidosis (<b>RTA</b>).</span></p><h3><b>2. Severe Acute Malnutrition: Marasmus vs. Kwashiorkor</b></h3><table class=\"t \"><tr><td><p><b>Feature</b></p></td><td><p><b>Marasmus </b><i><b>(Severe Calorie + Protein Deficiency)</b></i></p></td><td><p><b>Kwashiorkor </b><i><b>(Severe Protein Deficiency despite Carbohydrates)</b></i></p></td></tr><tr><td><p><b>Clinical Appearance</b></p></td><td><p>Severe wasting (<b>skin-and-bones</b>, \"old man\" wizened face, loss of buccal fat pads); <b>NO edema</b></p></td><td><p><b>Bilateral pitting edema</b> (legs/face/ascites), moon face, <b>fatty liver (hepatomegaly)</b>, <b>\"Flaky Paint\" dermatitis</b>, sparse reddish-depigmented hair (<b>Flag sign</b>)</p></td></tr><tr><td><p><b>Appetite &amp; Mood</b></p></td><td><p>Alert, irritable, <b>ravenous appetite</b></p></td><td><p>Lethargic, apathetic, <b>poor appetite</b></p></td></tr></table><ul>\n<li class=\"l1\"><b>CRITICAL TREATMENT WARNING (Prevent Fatal Refeeding Syndrome!):</b></li>\n<li class=\"l2\"><b>Phase 1 (Stabilization — Days 1–7):</b> Treat hypoglycemia, hypothermia, dehydration (use <b>ReSoMal</b> [low Na+, high K+] — avoid aggressive IV fluids unless in shock!), give empirical antibiotics, start <b>low-calorie/low-protein F-75 formula</b> slowly! (<b>DO NOT give Iron during Phase 1</b> — promotes bacterial growth and oxidative stress; add Iron ONLY in Phase 2 Rehabilitation with <b>F-100 / RUTF</b>!).</li>\n</ul>\n<p class=\"muted\"><i>End of Part 6A.</i></p><nav class=\"un\"><button class=\"nv\" data-u=\"u125\">← Case 14</button><button class=\"nv\" data-u=\"u127\">Case 16 →</button></nav></article><article class=\"view unit\" id=\"u127\" hidden style=\"--c:#00897b\"><button class=\"back\" data-p=\"6\">← Pediatrics</button><header class=\"uh\"><span class=\"ul\">Case 16</span><h1>Febrile Seizures &amp; Pediatric Status Epilepticus</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Febrile+Seizures+%26+Pediatric+Status+Epilepticus\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p><b>Febrile Seizure:</b> A seizure accompanied by fever (<b>≥ 38.0°C</b>) in a child aged <b>6 months – 5 years</b> (60 months) <b>WITHOUT</b> central nervous system (<b>CNS</b>) infection, metabolic imbalance, or prior afebrile seizures.</p><h3><b>2. Classification (Simple vs. Complex Febrile Seizure)</b></h3><table class=\"t \"><tr class=\"hd\"><th><p><b>Feature</b></p></th><th><p><b>Simple Febrile Seizure (~80%)</b></p></th><th><p><b>Complex Febrile Seizure (~20%)</b></p></th></tr><tr><td><p><b>Duration</b></p></td><td><p><b>&lt; 15 minutes</b></p></td><td><p><b>≥ 15 minutes</b></p></td></tr><tr><td><p><b>Semiology</b></p></td><td><p><b>Generalized</b> (tonic-clonic)</p></td><td><p><b>Focal</b> (one-sided / Todd’s paralysis)</p></td></tr><tr><td><p><b>Recurrence in 24 hrs</b></p></td><td><p><b>Single</b> episode in 24 hrs</p></td><td><p><b>≥ 2 episodes</b> within 24 hours</p></td></tr><tr><td><p><b>Prognosis</b></p></td><td><p><b>Benign!</b> (~1–2% risk of epilepsy, near normal; ~30% recurrence)</p></td><td><p>Slightly higher epilepsy risk (~5–10%); needs closer workup</p></td></tr></table><h3><b>3. Etiology (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Viral Illnesses (Most Common):</b> <b>HHV-6</b> (Roseola Infantum — classic!), Influenza, Adenovirus, Rhinovirus.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Bacterial / Post-Vaccination:</b> Acute Otitis Media, <b>UTI</b>, post-MMR or DTaP fever.</span></p><h3><b>4. Investigations (Minimum Testing for Simple Febrile Seizure!)</b></h3><ul>\n<li class=\"l1\"><b>Simple Febrile Seizure (Well-appearing after post-ictal recovery):</b> <mark class=\"hl mech\"><b>NO routine blood labs, NO EEG, and NO Brain CT/MRI needed!</b></mark> Focus solely on finding the <b>source of fever</b>!</li>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Indications for Lumbar Puncture (Rule Out Meningitis!):</b></mark></li>\n<li class=\"l2\">Any <b>meningeal signs</b> (neck stiffness, bulging fontanelle, petechiae, persistent lethargy).</li>\n<li class=\"l2\">Strongly consider in <b>infants 6–12 months</b> who are <b>unvaccinated</b> (against <i>Hib/S. pneumoniae</i>) or <b>already on antibiotics</b> (masks meningitis!).</li>\n</ul><h3><b>5. Treatment</b></h3><ul>\n<li class=\"l1\"><b>If Seizure Has Stopped:</b> Antipyretics (<b>Acetaminophen</b> 15 mg/kg/dose or <b>Ibuprofen</b> 10 mg/kg/dose &gt; 6 mos) for comfort <i>(NOTE: Antipyretics do NOT prevent recurrent febrile seizures!)</i> + Reassure parents + NO long-term antiseizure medications!</li>\n<li class=\"l1\"><b>Acute Seizure Lasting ≥ 5 Minutes (Pediatric Status Epilepticus Protocol):</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>0–5 Min (ABCDE + Glucose!):</b> Airway, Oxygen, lateral recovery position; <mark class=\"hl lab\"><b>CHECK CAPILLARY GLUCOSE IMMEDIATELY</b></mark> (give IV <b>D10W 2–5 mL/kg</b> if hypoglycemic!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>5–10 Min (1st-Line Benzodiazepine):</b> <b>IV Lorazepam 0.1 mg/kg</b> (max 4 mg) OR <b>IV Diazepam 0.2–0.3 mg/kg</b>; if NO IV access -&gt; <b>IM Midazolam 0.2 mg/kg</b> (or Buccal/Intranasal Midazolam 0.2–0.5 mg/kg, or <b>Rectal Diazepam 0.5 mg/kg</b>)! Repeat once in 5 min if still seizing.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>20 Min (2nd-Line):</b> <b>IV Levetiracetam (60 mg/kg)</b> OR <b>IV Fosphenytoin/Phenytoin (20 mg/kg)</b> OR <b>IV Valproate</b> (avoid Valproate in &lt; 2 yrs / mitochondrial disease!).</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>40 Min (Refractory):</b> ICU Intubation + <b>IV Midazolam / Propofol / Phenobarbital</b> infusion.</span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u126\">← Case 15</button><button class=\"nv\" data-u=\"u128\">Case 17 →</button></nav></article><article class=\"view unit\" id=\"u128\" hidden style=\"--c:#00897b\"><button class=\"back\" data-p=\"6\">← Pediatrics</button><header class=\"uh\"><span class=\"ul\">Case 17</span><h1>Pediatric Bacterial Meningitis &amp; Encephalitis</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pediatric+Bacterial+Meningitis+%26+Encephalitis\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Bacterial Meningitis:</b></mark> Acute purulent infection of the leptomeninges and <mark class=\"hl mech\"><b>CSF</b></mark> (Cerebrospinal Fluid) space.</li>\n<li class=\"l1\"><b>Encephalitis:</b> Inflammation of the <b>brain parenchyma</b> (characterized by <b>altered mental status / behavioral change / seizures / focal deficits</b>!).</li>\n</ul><h3><b>2. Etiology of Bacterial Meningitis (Separated by Age)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Neonates (&lt; 1–3 Months):</b> <mark class=\"hl lab\"><b>GBS</b></mark> (<i>S. agalactiae</i>), <i><b>E. coli</b></i>, <i>Listeria monocytogenes</i>.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Infants &amp; Children (≥ 3 Months – 18 Years):</b> <i><b>Streptococcus pneumoniae</b></i> (#1), <i><b>Neisseria meningitidis</b></i> (Meningococcus — petechial/purpuric rash, outbreaks!), <i>Haemophilus influenzae</i> type b (unvaccinated).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><mark class=\"hl lab\"><b>Viral Meningitis / Encephalitis:</b></mark> <b>Enteroviruses</b> (#1 viral meningitis!), <b>HSV-1</b> (Herpes Simplex Virus — hemorrhagic temporal lobe encephalitis -&gt; high mortality if missed!).</span></p><h3><b>3. Clinical Picture</b></h3><ul>\n<li class=\"l1\"><b>Infants (&lt; 12 Months — NO Neck Stiffness Usually!):</b> Fever OR hypothermia, <b>bulging anterior fontanelle</b>, high-pitched inconsolable cry (\"paradoxical irritability\" — cries MORE when held/rocked!), lethargy, poor feeding, seizures.</li>\n<li class=\"l1\"><b>Older Children:</b> Fever, headache, vomiting, photophobia, <b>nuchal rigidity</b>, <b>Kernig’s sign</b> (pain/resistance extending knee with hip flexed 90°), <b>Brudzinski’s sign </b>(involuntary hip/knee flexion when neck is flexed), <b>non-blanching petechiae/purpura</b> (<i>N. meningitidis</i>!).</li>\n</ul><h3><b>4. Investigations (NEVER DELAY IV ANTIBIOTICS FOR CT OR LUMBAR PUNCTURE!)</b></h3><ul>\n<li class=\"l1\">Draw <b>Blood Cultures</b> + <mark class=\"hl mech\"><b>CBC/CRP/Glucose/Electrolytes</b></mark> immediately.</li>\n<li class=\"l1\"><mark class=\"hl mech\"><b>Lumbar Puncture (CSF Analysis):</b></mark> <i>(Perform </i><i><b>CT Brain FIRST</b></i><i> ONLY if immunocompromised, focal neuro deficits, papilledema, or coma/herniation signs — give empirical IV antibiotics BEFORE CT!)</i></li>\n</ul><table class=\"t wide\"><tr><td><p><mark class=\"hl mech\"><b>CSF Parameter</b></mark></p></td><td><p><mark class=\"hl rx\"><b>Normal</b></mark></p></td><td><p><mark class=\"hl lab\"><b>Bacterial Meningitis</b></mark></p></td><td><p><mark class=\"hl lab\"><b>Viral Meningitis</b></mark></p></td><td><p><mark class=\"hl lab\"><b>TB Meningitis </b></mark><i><b>(Important in Egypt!)</b></i></p></td></tr><tr><td><p><b>Opening Pressure</b></p></td><td><p>10–20 cmH2O</p></td><td><p><b>High (&gt; 20–30)</b></p></td><td><p>Normal / Mildly high</p></td><td><p><b>Very High</b></p></td></tr><tr><td><p><mark class=\"hl mech\"><b>WBC Count &amp; Type</b></mark></p></td><td><p>&lt; 5 (Lymphs)</p></td><td><p><mark class=\"hl mech\"><b>&gt; 1,000 (Neutrophils / PMNs)</b></mark></p></td><td><p><b>10–500 (Lymphocytes)</b></p></td><td><p><b>100–500 (Lymphocytes)</b></p></td></tr><tr><td><p><b>Protein</b></p></td><td><p>15–45 mg/dL</p></td><td><p><b>Markedly High (&gt; 100–500)</b></p></td><td><p>Normal / Mildly high (&lt; 100)</p></td><td><p><b>Very High (&gt; 100–500; \"cobweb\" clot)</b></p></td></tr><tr><td><p><b>Glucose</b></p></td><td><p>&gt; 2/3 serum</p></td><td><p><b>VERY LOW (&lt; 40 or &lt; 40% serum)</b></p></td><td><p><mark class=\"hl rx\"><b>Normal</b></mark></p></td><td><p><b>Low (&lt; 40)</b></p></td></tr></table><h3><b>5. Treatment</b></h3><ul>\n<li class=\"l1\"><b>Empirical IV Antibiotics Immediately:</b></li>\n<li class=\"l2\">&lt; 1 Month: <mark class=\"hl rx\"><b>IV Ampicillin + Cefotaxime</b></mark> (or Gentamicin).</li>\n<li class=\"l2\">≥ 1–3 Months: <mark class=\"hl rx\"><b>IV Ceftriaxone (100 mg/kg/day) PLUS IV Vancomycin (60 mg/kg/day)</b></mark> (covers resistant <i>S. pneumoniae</i>!).</li>\n<li class=\"l2\"><i>If Encephalitis (Altered Mental Status / Temporal Lobe / Seizures) Suspected:</i> <mark class=\"hl rx\"><b>ADD IV Acyclovir</b></mark> immediately!</li>\n<li class=\"l1\"><mark class=\"hl rx\"><b>Adjunctive Dexamethasone (0.15 mg/kg IV q6h × 2–4 days):</b></mark> Give <b>before or with first antibiotic dose</b> in children &gt; 6 weeks to prevent <b>sensorineural hearing loss </b>(especially <i>Hib/Pneumococcus</i>)!</li>\n<li class=\"l1\"><b>Chemoprophylaxis for Close Contacts of </b><i><b>N. meningitidis</b></i><b>:</b> <b>Rifampin</b> (2 days) or single-dose <mark class=\"hl rx\"><b>Ciprofloxacin / Ceftriaxone</b></mark> .</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u127\">← Case 16</button><button class=\"nv\" data-u=\"u129\">Case 18 →</button></nav></article><article class=\"view unit\" id=\"u129\" hidden style=\"--c:#00897b\"><button class=\"back\" data-p=\"6\">← Pediatrics</button><header class=\"uh\"><span class=\"ul\">Case 18</span><h1>Acute Rheumatic Fever (ARF — PEDIATRIC MANAGEMENT)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Rheumatic+Fever+%28ARF+%E2%80%94+PEDIATRIC+MANAGEMENT%29\">🔍 Search on Google</a></header><p><i>(See Cardiology Case 21 for complete Jones Criteria — here are the essential </i><i><b>Pediatric Clinical Distinctions</b></i><i>!)</i></p>\n<ul>\n<li class=\"l1\"><b>Classic Egyptian Pediatric Presentation:</b> Child aged <b>5–15 years</b> presenting 2–4 weeks after untreated sore throat with <b>painful swollen knee/ankle</b> that \"jumps\" to the opposite elbow/wrist (<b>migratory polyarthritis</b>), OR subtle tachycardia out of proportion to fever / sleeping tachycardia (<b>carditis</b>), OR a school-aged girl suddenly dropping pencils, having messy handwriting, and emotional outbursts (<b>Sydenham Chorea</b>!).</li>\n<li class=\"l1\"><b>Pediatric Differential Trap:</b> Always distinguish ARF from <mark class=\"hl lab\"><b>Septic Arthritis</b></mark> (single joint, extremely toxic, pus on tap), <b>JIA</b> (Juvenile Idiopathic Arthritis — chronic &gt; 6 weeks, morning stiffness, no dramatic 48-hr aspirin response), and <mark class=\"hl lab\"><b>ALL</b></mark> (Acute Lymphoblastic Leukemia — bone pain + cytopenias!).</li>\n<li class=\"l1\"><b>Pediatric Dosing Pearls:</b></li>\n<li class=\"l2\"><i>GAS Eradication:</i> Single <b>IM Benzathine Penicillin G</b> (≤ 27 kg: 600,000 U; &gt; 27 kg: 1.2 million U) OR Oral Amoxicillin 50 mg/kg/day × 10 days.</li>\n<li class=\"l2\"><i>Arthritis:</i> <mark class=\"hl rx\"><b>Aspirin</b></mark> 80–100 mg/kg/day divided QID (or <b>Naproxen</b> 10–20 mg/kg/day BID — safer, avoids Reye syndrome risk in viral overlap!).</li>\n<li class=\"l2\"><i>Carditis:</i> <mark class=\"hl rx\"><b>Oral Prednisolone 2 mg/kg/day</b></mark> (max 60–80 mg) × 2–3 weeks, then taper.</li>\n<li class=\"l2\"><i>Sydenham Chorea:</i> Self-limited (weeks–months); <b>Valproate</b> or <b>Carbamazepine</b> (or Haloperidol/Risperidone) if severe impairing movements.</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u128\">← Case 17</button><button class=\"nv\" data-u=\"u130\">Case 19 →</button></nav></article><article class=\"view unit\" id=\"u130\" hidden style=\"--c:#00897b\"><button class=\"back\" data-p=\"6\">← Pediatrics</button><header class=\"uh\"><span class=\"ul\">Case 19</span><h1>Kawasaki Disease (MUCOCUTANEOUS LYMPH NODE SYNDROME)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Kawasaki+Disease+%28MUCOCUTANEOUS+LYMPH+NODE+SYNDROME%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Acute idiopathic systemic <b>medium-vessel vasculitis</b> predominantly affecting <b>children &lt; 5 years old</b>, with a critical predilection for the <b>coronary arteries</b>. <b>#1 cause of acquired heart disease in children in developed nations!</b></p><h3><b>2. Diagnostic Criteria (Persistent High Fever ≥ 5 Days + ≥ 4 of 5 Clinical Features)</b></h3><p><i>(Mnemonic: </i><i><b>\"CRASH &amp; Burn\"</b></i><i> — </i><i><b>Burn</b></i><i> = Fever ≥ 5 days!)</i></p>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>C</b>onjunctivitis: <b>Bilateral non-purulent (limbic-sparing)</b> bulbar conjunctival injection (no pus!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>R</b>ash: Polymorphous generalized rash (maculopapular/morbilliform/scarlatiniform; prominent in groin!).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>A</b>denopathy: <b>Acute unilateral cervical lymphadenopathy</b> (≥ 1 node ≥ 1.5 cm).</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>S</b>trawberry Tongue &amp; Oral Mucositis: Red cracked dry lips, erythematous pharynx, <b>strawberry tongue</b>.</span></p>\n<p class=\"num\"><span class=\"n\">5.</span><span class=\"nt\"><b>H</b>ands &amp; Feet: Acute erythema &amp; painful non-pitting edema of palms/soles -&gt; followed in Week 2–3 by <b>periungual desquamation</b> (skin peeling from fingertips/toes!).</span></p><p class=\"muted\"><i>(Extreme irritability is a classic clinical clue! Incomplete/Atypical Kawasaki can occur in infants &lt; 6 months with prolonged fever alone!)</i></p><h3><b>3. Investigations &amp; Complications</b></h3><ul>\n<li class=\"l1\"><b>Labs (Supportive):</b> Marked <b>Leukocytosis</b>, <mark class=\"hl mech\"><b>Markedly Elevated ESR &amp; CRP</b></mark> , <b>Thrombocytosis</b> (platelets &gt; 450,000–1,000,000 in <b>Week 2</b>!), sterile pyuria, mild transaminitis, hypoalbuminemia.</li>\n<li class=\"l1\"><b>Mandatory Cardiac Test:</b> <mark class=\"hl mech\"><b>Transthoracic Echocardiogram</b></mark> at diagnosis, Week 2, and Week 6–8!</li>\n<li class=\"l1\"><b>Most Feared Complication:</b> <b>Coronary Artery Aneurysms (CAAs)</b> (~25% if untreated -&gt; drops to &lt; 4% if treated within 10 days!), MI, sudden death.</li>\n</ul><h3><b>4. Treatment (Start Within 10 Days of Fever Onset!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><mark class=\"hl rx\"><b>IVIG (Intravenous Immunoglobulin): 2 g/kg</b></mark> single infusion over 10–12 hours!</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><mark class=\"hl rx\"><b>High-Dose Aspirin:</b></mark> <b>30–50 mg/kg/day</b> (or 80–100) divided QID until afebrile for 48–72 hrs -&gt; then <mark class=\"hl rx\"><b>Low-Dose Aspirin (3–5 mg/kg/day)</b></mark> antiplatelet dose for <b>6–8 weeks</b> (lifelong if coronary aneurysms persist!). <i>(Note: Kawasaki is the rare pediatric exception where Aspirin is used — vaccinate against Influenza/Varicella to avoid Reye syndrome!)</i></span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u129\">← Case 18</button><button class=\"nv\" data-u=\"u131\">Case 20 →</button></nav></article><article class=\"view unit\" id=\"u131\" hidden style=\"--c:#00897b\"><button class=\"back\" data-p=\"6\">← Pediatrics</button><header class=\"uh\"><span class=\"ul\">Case 20</span><h1>Henoch-Schönlein Purpura (HSP / IgA VASCULITIS)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Henoch-Sch%C3%B6nlein+Purpura+%28HSP+%2F+IgA+VASCULITIS%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p><b>#1 systemic vasculitis of childhood</b> (peak age <b>4–7 years</b>); an <b>IgA immune-complex small-vessel (leukocytoclastic) vasculitis</b>, typically occurring <b>1–3 weeks after an URTI</b> (e.g., GAS or viral).</p><h3><b>2. Clinical Picture (Classic Tetrad — Platelets Are NORMAL/HIGH!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Palpable Purpura (100% — Mandatory Criterion):</b> Symmetrical non-blanching raised purpuric rash concentrated over <b>buttocks and extensor lower extremities </b>(gravity-dependent!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Arthralgia / Arthritis (~75%):</b> Swollen painful <b>knees &amp; ankles</b> (transient, non-deforming).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Abdominal Pain (~65%):</b> Colicky pain, nausea/vomiting, occult/gross GI bleeding -&gt; <b>RISK OF ILEO-ILEAL INTUSSUSCEPTION!</b></span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Renal Disease (~30–50%):</b> Microscopic/gross hematuria, proteinuria (<b>IgA Nephropathy</b> spectrum — major determinant of long-term prognosis!).</span></p><h3><b>3. Investigations &amp; Treatment</b></h3><ul>\n<li class=\"l1\"><b>Labs:</b> <mark class=\"hl mech\"><b>CBC (NORMAL or HIGH Platelets</b></mark> — IMMEDIATELY distinguishes HSP from ITP and Meningococcemia!), Normal PT/aPTT, <mark class=\"hl mech\"><b>Urinalysis</b></mark> (check for hematuria/proteinuria at diagnosis &amp; weekly/monthly for <b>6 months</b>!), <mark class=\"hl mech\"><b>RFTs</b></mark> , Stool occult blood (+ Abdominal Ultrasound if severe colicky pain to rule out intussusception!).</li>\n<li class=\"l1\"><b>Treatment:</b></li>\n<li class=\"l2\"><i>Mild (Rash + Joint pain):</i> <b>Self-limited!</b> Supportive care, hydration, rest, <b>Acetaminophen</b> (or cautious NSAIDs if NO GI bleed/renal disease).</li>\n<li class=\"l2\"><i>Severe Colicky Abdominal Pain / GI Bleed / Severe Nephritis:</i> <mark class=\"hl rx\"><b>Oral Prednisolone 1–2 mg/kg/day</b></mark> for 1–2 weeks then taper (relieves GI/joint pain rapidly, though doesn't prevent nephritis!).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u130\">← Case 19</button><button class=\"nv\" data-u=\"u132\">Case 21 →</button></nav></article><article class=\"view unit\" id=\"u132\" hidden style=\"--c:#00897b\"><button class=\"back\" data-p=\"6\">← Pediatrics</button><header class=\"uh\"><span class=\"ul\">Case 21</span><h1>Classic Childhood Viral Exanthems &amp; Scarlet Fever</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Classic+Childhood+Viral+Exanthems+%26+Scarlet+Fever\">🔍 Search on Google</a></header><table class=\"t \"><tr class=\"hd\"><th><p><b>Disease &amp; Pathogen</b></p></th><th><p><b>Classic Prodrome</b></p></th><th><p><b>Rash Morphology &amp; Spread</b></p></th><th><p><b>Pathognomonic Clue &amp; Key Action</b></p></th></tr><tr><td><p><b>Measles (Rubeola)</b> <i>(Paramyxovirus)</i></p></td><td><p>High fever + <b>\"3 Cs\": Cough, Coryza, Conjunctivitis</b></p></td><td><p>Blotchy maculopapular rash starting on <b>hairline/face -&gt; spreads downward </b>(coalesces)</p></td><td><p><b>Koplik’s Spots</b> (tiny white grains on buccal mucosa opposite molars)! Give <b>Vitamin A </b>(reduces mortality &amp; blindness!); isolate (airborne!).</p></td></tr><tr><td><p><b>Rubella (German Measles) </b><i>(Togavirus)</i></p></td><td><p>Mild fever + <b>Posterior auricular / suboccipital lymphadenopathy</b></p></td><td><p>Fine pink maculopapular rash <b>face -&gt; down </b>(resolves in <b>3 days</b>!)</p></td><td><p><b>Forchheimer spots</b> (palate); <b>Congenital Rubella Syndrome</b> (cataracts, PDA, deafness) if pregnant mother infected!</p></td></tr><tr><td><p><b>Roseola Infantum (Exanthem Subitum)</b> <i>(HHV-6)</i></p></td><td><p><b>3–5 days of HIGH Fever (&gt; 39.5°C)</b> in well-appearing infant (6–24 mos) -&gt; <b>Febrile Seizure!</b></p></td><td><p><b>Rash appears AFTER fever abruptly resolves!</b> (Pink macules on <b>trunk -&gt; spreads outward</b>)</p></td><td><p><b>\"Fever breaks -&gt; Rash wakes!\"</b> Benign, supportive care only.</p></td></tr><tr><td><p><b>Erythema Infectiosum (5th Disease) </b><i>(Parvovirus B19)</i></p></td><td><p>Mild fever, malaise</p></td><td><p><b>\"Slapped-Cheek\"</b> bright red face -&gt; <b>lacy reticular rash</b> on trunk/limbs</p></td><td><p>Causes <b>Aplastic Crisis</b> in <b>Sickle Cell / Thalassemia</b> patients &amp; hydrops fetalis in pregnancy!</p></td></tr><tr><td><p><b>Varicella (Chickenpox)</b> <i>(Varicella-Zoster Virus)</i></p></td><td><p>Fever, malaise 1–2 days</p></td><td><p><b>Pruritic vesicles on erythematous base (\"Dewdrop on a rose petal\")</b> in <mark class=\"hl lab\"><b>ALL STAGES simultaneously</b></mark> (papules, vesicles, crusts), central -&gt; outward</p></td><td><p><mark class=\"hl rx\"><b>Avoid Aspirin</b></mark> (Reye syndrome!); give <mark class=\"hl rx\"><b>Acyclovir</b></mark> if immunocompromised, adolescents, or neonates; airborne + contact isolation until ALL lesions crust!</p></td></tr><tr><td><p><b>Scarlet Fever</b> <i>(GAS Exotoxin)</i></p></td><td><p><b>Acute pharyngitis + Fever + Strawberry tongue</b></p></td><td><p>Fine erythematous <b>\"Sandpaper\" rash </b>blanching on pressure + <b>Pastia’s lines </b>(accentuated in skin folds) + circumoral pallor</p></td><td><p><b>Bacterial!</b> Treat with <mark class=\"hl rx\"><b>Amoxicillin / Penicillin × 10 days</b></mark> (prevents ARF!).</p></td></tr></table><nav class=\"un\"><button class=\"nv\" data-u=\"u131\">← Case 20</button><button class=\"nv\" data-u=\"u133\">Case 22 →</button></nav></article><article class=\"view unit\" id=\"u133\" hidden style=\"--c:#00897b\"><button class=\"back\" data-p=\"6\">← Pediatrics</button><header class=\"uh\"><span class=\"ul\">Case 22</span><h1>Mumps &amp; Pertussis (WHOOPING COUGH)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Mumps+%26+Pertussis+%28WHOOPING+COUGH%29\">🔍 Search on Google</a></header><h3><b>A. Mumps (</b><b>Paramyxovirus</b><b>)</b></h3><ul>\n<li class=\"l1\"><b>Clinical Picture:</b> Fever, malaise -&gt; painful unilateral/bilateral <b>Parotid Gland Swelling</b> (earlobe pushed up/out, obscures angle of mandible, pain worsened by sour foods!).</li>\n<li class=\"l1\"><b>Complications:</b> <mark class=\"hl lab\"><b>Aseptic Meningitis</b></mark> (#1 CNS complication), <b>Epididymo-orchitis</b> (post-pubertal males — unilateral painful swollen testis, rarely causes sterility), <b>Oophoritis</b>, <b>Pancreatitis</b>, Sensorineural deafness.</li>\n<li class=\"l1\"><b>Treatment:</b> Supportive (analgesia, cold/warm packs, soft bland diet, scrotal support if orchitis); droplet isolation for 5 days after parotitis onset.</li>\n</ul><h3><b>B. Pertussis (</b><b>Bordetella pertussis</b><b> — \"100-Day Cough\")</b></h3><ul>\n<li class=\"l1\"><b>Clinical Picture (3 Stages):</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><i>Catarrhal (1–2 wks):</i> Mild rhinorrhea/cough (MOST contagious!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><i>Paroxysmal (2–6 wks):</i> Severe bursts of rapid staccato coughs followed by a massive <b>inspiratory \"Whoop\"</b> + <b>post-tussive vomiting</b> (and <b>apnea/cyanosis in infants &lt; 3–6 months</b> without a whoop!).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><i>Convalescent (weeks–months):</i> Gradual cough resolution.</span></p>\n<ul>\n<li class=\"l1\"><b>Diagnosis:</b> Nasopharyngeal swab <b>PCR</b> (+ marked <b>Lymphocytosis</b> on CBC!).</li>\n<li class=\"l1\"><b>Treatment:</b> <mark class=\"hl rx\"><b>Azithromycin</b></mark> (10 mg/kg/day × 5 days) or Clarithromycin/Erythromycin (reduces infectivity in catarrhal phase, rarely shortens paroxysms once started!) + <mark class=\"hl lab\"><b>Treat ALL household contacts</b></mark> with Azithromycin prophylaxis! Admit infants &lt; 6 months for apnea monitoring!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u132\">← Case 21</button><button class=\"nv\" data-u=\"u134\">Case 23 →</button></nav></article><article class=\"view unit\" id=\"u134\" hidden style=\"--c:#00897b\"><button class=\"back\" data-p=\"6\">← Pediatrics</button><header class=\"uh\"><span class=\"ul\">Case 23</span><h1>Pediatric Urinary Tract Infection (UTI) &amp; VUR</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pediatric+Urinary+Tract+Infection+%28UTI%29+%26+VUR\">🔍 Search on Google</a></header><h3><b>1. Clinical Presentation by Age</b></h3><ul>\n<li class=\"l1\"><b>Infants / &lt; 2 Years:</b> <b>UNEXPLAINED FEVER (&gt; 38°C)</b> without a clear focus! (Plus irritability, vomiting, poor feeding, foul-smelling urine, prolonged jaundice in neonates!).</li>\n<li class=\"l1\"><b>Older Children:</b> Dysuria, frequency, urgency, new-onset secondary enuresis (day/night wetting), abdominal/flank pain + fever (pyelonephritis).</li>\n</ul><h3><b>2. Diagnosis (CRITICAL SAMPLE COLLECTION RULE!)</b></h3><ul>\n<li class=\"l1\"><b>NEVER use a sticky perineal bag for Urine Culture</b> (unacceptable false-positive skin contamination — only useful if negative to rule out UTI!).</li>\n<li class=\"l1\">Collect via <b>Clean-Catch Midstream</b> (toilet-trained) OR <b>Transurethral Catheterization / Suprapubic Aspiration</b> (non-toilet-trained febrile infant)!</li>\n<li class=\"l1\"><b>Diagnosis:</b> Pyuria (<mark class=\"hl mech\"><b> ≥ 5 WBC/HPF</b></mark> or Leukocyte Esterase +) / Nitrites + <b>Positive Urine Culture</b> (≥ 50,000 CFU/mL on catheter sample).</li>\n</ul><h3><b>3. Treatment &amp; Mandatory Imaging</b></h3><ul>\n<li class=\"l1\"><b>Febrile UTI / Pyelonephritis:</b></li>\n<li class=\"l2\">&lt; 2–3 Months or Toxic/Vomiting: <mark class=\"hl rx\"><b>Admit + IV Ceftriaxone/Cefotaxime</b></mark> (+ Ampicillin in neonates).</li>\n<li class=\"l2\">&gt; 3 Months, Well-appearing, Tolerating PO: <b>Oral Cefixime</b> (8 mg/kg/day) or <b>Cefdinir</b> or <mark class=\"hl rx\"><b>Amoxicillin-Clavulanate</b></mark> for <b>7–10 days</b>.</li>\n<li class=\"l1\"><b>Cystitis (Afebrile &gt; 2 yrs):</b> Oral Amoxicillin-Clavulanate, Cefixime, or TMP-SMX × 3–5 days.</li>\n<li class=\"l1\"><b>Post-UTI Imaging (AAP Guidelines for Febrile UTI &lt; 2–3 Years):</b></li>\n<li class=\"l2\"><b>Renal &amp; Bladder Ultrasound (RBUS)</b> after <b>FIRST</b> febrile UTI (detects hydronephrosis/anomalies).</li>\n<li class=\"l2\"><b>VCUG</b> (Voiding Cystourethrogram) if RBUS is abnormal OR after <b>SECOND</b> febrile UTI -&gt; diagnoses <b>Vesicoureteral Reflux (VUR)</b>!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u133\">← Case 22</button><button class=\"nv\" data-u=\"u135\">Case 24 →</button></nav></article><article class=\"view unit\" id=\"u135\" hidden style=\"--c:#00897b\"><button class=\"back\" data-p=\"6\">← Pediatrics</button><header class=\"uh\"><span class=\"ul\">Case 24</span><h1>Pediatric Nephrotic Syndrome (MINIMAL CHANGE DISEASE)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pediatric+Nephrotic+Syndrome+%28MINIMAL+CHANGE+DISEASE%29\">🔍 Search on Google</a></header><h3><b>1. Definition &amp; Diagnostic Tetrad</b></h3><p>Glomerular podocyte injury causing massive proteinuria (typically <mark class=\"hl lab\"><b>Minimal Change Disease [MCD] ~85–90%</b></mark> in children aged <b>2–6 years</b>):</p>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Nephrotic-Range Proteinuria:</b> <b>Urine Protein/Creatinine Ratio &gt; 2 mg/mg</b> (or ≥ 3+/4+ dipstick, &gt; 40 mg/m²/hr).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Hypoalbuminemia (&lt; 2.5 g/dL).</b></span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Generalized Edema</b> (starts as <b>periorbital puffiness in the morning</b>, progressing to ascites, scrotal/labial edema, pleural effusion!).</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Hyperlipidemia</b> (high cholesterol/TG).</span></p>\n<p><i>(Note: </i><i><b>NO gross hematuria, NO hypertension, Normal C3 complement, Normal Creatinine</b></i><i> in typical MCD!)</i></p><h3><b>2. Complications (High Yield!)</b></h3><ul>\n<li class=\"l1\"><b>Infections (#1 Cause of Mortality):</b> Especially <mark class=\"hl lab\"><b>SBP (Spontaneous Bacterial Peritonitis)</b></mark> caused by <i><b>Streptococcus pneumoniae</b></i> (due to urinary loss of IgG and Complement Factor B!).</li>\n<li class=\"l1\"><b>Hypercoagulability / Thrombosis:</b> Renal vein thrombosis, DVT, PE (urinary loss of <b>Antithrombin III</b>!).</li>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Hypovolemic Shock / AKI</b></mark> (from low intravascular oncotic pressure despite massive third-space edema!).</li>\n</ul><h3><b>3. Treatment</b></h3><ul>\n<li class=\"l1\"><b>First-Line (NO Renal Biopsy Needed Initially if Typical MCD Aged 1–10 Yrs!):</b></li>\n<li class=\"l2\"><mark class=\"hl rx\"><b>Oral Prednisolone 60 mg/m²/day (or 2 mg/kg/day, max 60 mg)</b></mark> daily for <b>4–6 weeks</b>, followed by <b>40 mg/m² every other day</b> for <b>4–6+ weeks</b> then slow taper! (&gt; 90% achieve complete remission within 2–4 weeks!).</li>\n<li class=\"l1\"><b>Supportive:</b> Low-sodium diet during edema; <b>cautious</b> Furosemide ONLY if severe symptomatic edema/respiratory distress <b>combined with 25% IV Albumin</b> (never give diuretics alone if intravascularly depleted!); <b>Pneumococcal vaccination</b>.</li>\n<li class=\"l1\"><i>Steroid-Resistant or Frequently Relapsing:</i> Renal biopsy (rule out <b>FSGS</b>) -&gt; add <mark class=\"hl rx\"><b>Tacrolimus / Cyclosporine / Cyclophosphamide / Rituximab / MMF</b></mark> .</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u134\">← Case 23</button><button class=\"nv\" data-u=\"u136\">Case 25 →</button></nav></article><article class=\"view unit\" id=\"u136\" hidden style=\"--c:#00897b\"><button class=\"back\" data-p=\"6\">← Pediatrics</button><header class=\"uh\"><span class=\"ul\">Case 25</span><h1>Acute Post-Streptococcal Glomerulonephritis (PSGN)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Post-Streptococcal+Glomerulonephritis+%28PSGN%29\">🔍 Search on Google</a></header><h3><b>1. Definition &amp; Etiology</b></h3><p>Immune-complex-mediated <mark class=\"hl lab\"><b>Nephritic Syndrome</b></mark> occurring in children (peak <b>5–12 years</b>) <b>1–2 weeks after GAS Pharyngitis</b> OR <b>3–6 weeks after GAS Skin Infection (Impetigo)</b>.</p><h3><b>2. Clinical Picture (Classic Nephritic Triad)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Hematuria:</b> Dark <b>\"Coca-Cola / Tea-colored\" smoky urine</b> + <b>Dysmorphic RBCs &amp; RBC Casts</b> on urine microscopy!</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Hypertension</b> (mild-to-severe — risk of <b>Hypertensive Encephalopathy / Seizures</b>!) + Oliguria.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Edema:</b> Periorbital / facial puffiness + mild peripheral edema (fluid overload!).</span></p><h3><b>3. Investigations &amp; Comparison with MCD</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl mech\"><b>Urinalysis:</b></mark> RBCs, <b>RBC casts</b>, mild-to-moderate proteinuria.</li>\n<li class=\"l1\"><b>Serology:</b> <b>LOW Serum C3 Complement</b> (normalized within <b>6–8 weeks</b>! — <i>if C3 stays low &gt; 8 weeks, biopsy to rule out MPGN/Lupus!</i>), Elevated <b>ASOT</b> (post-pharyngitis) or <b>Anti-DNase B</b> (post-impetigo!).</li>\n</ul><h3><b>4. Treatment (Supportive — Self-Limited &gt; 95% Complete Recovery!)</b></h3><ul>\n<li class=\"l1\"><b>Strict Fluid &amp; Sodium Restriction</b> + <mark class=\"hl rx\"><b>IV/Oral Furosemide</b></mark> (first-line for edema &amp; hypertension!) +/- <mark class=\"hl rx\"><b>CCB (Amlodipine/Nifedipine)</b></mark> if severe HTN.</li>\n<li class=\"l1\">Treat residual GAS with Penicillin/Amoxicillin (does not alter PSGN course, prevents spread). <i>Steroids are NOT indicated in typical PSGN!</i></li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u135\">← Case 24</button><button class=\"nv\" data-u=\"u137\">Case 26 →</button></nav></article><article class=\"view unit\" id=\"u137\" hidden style=\"--c:#00897b\"><button class=\"back\" data-p=\"6\">← Pediatrics</button><header class=\"uh\"><span class=\"ul\">Case 26</span><h1>Pediatric Immune Thrombocytopenic Purpura (ITP)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pediatric+Immune+Thrombocytopenic+Purpura+%28ITP%29\">🔍 Search on Google</a></header><h3><b>1. Definition &amp; Clinical Picture</b></h3><p>Autoimmune IgG destruction of platelets (<b>Platelets &lt; 100,000/mm³</b>, often <b>&lt; 20,000/mm³</b>) typically occurring <b>1–4 weeks after a viral URTI</b> in an <b>otherwise completely healthy, happy child (2–6 years)</b>!</p>\n<ul>\n<li class=\"l1\">Sudden onset of <b>petechiae, purpura, ecchymoses</b>, <b>epistaxis</b>, and <b>gingival bleeding</b> (\"wet bleeding\").</li>\n<li class=\"l1\"><b>CRITICAL EXAM RULE:</b> Child MUST have <b>NO fever, NO bone pain, NO lymphadenopathy, and NO hepatosplenomegaly</b> (if present -&gt; suspect <b>Acute Leukemia</b>!).</li>\n</ul><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><p><mark class=\"hl red\"><b>⚠ 2. Investigations &amp; Red Flag Rule</b></mark></p></div></div><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><ul>\n<li class=\"l1\"><mark class=\"hl mech\"><b>CBC + Peripheral Blood Smear:</b></mark> <b>Isolated Severe Thrombocytopenia</b> with <b>giant platelets</b>, <mark class=\"hl mech\"><b>NORMAL Hemoglobin (unless heavy bleeding), NORMAL WBC &amp; Differential, NO blasts!</b></mark></li>\n<li class=\"l1\"><i>Do NOT perform Bone Marrow Aspiration</i> in typical acute pediatric ITP unless atypical features exist (anemia, neutropenia, bone pain, hepatosplenomegaly, or before starting steroids if leukemia isn't excluded!).</li>\n</ul></div></div><h3><b>3. Treatment</b></h3><ul>\n<li class=\"l1\"><b>Skin-Only Mild Symptoms (Petechiae/Bruising, NO Active Mucosal Bleeding — Even if Platelets &lt; 20,000!):</b> <b>Observation &amp; Reassurance ONLY!</b> (~80% resolve spontaneously within 6 months!). Avoid contact sports, <mark class=\"hl rx\"><b>Aspirin, and NSAIDs</b></mark> !</li>\n<li class=\"l1\"><b>Active Mucosal Bleeding (\"Wet Bleeding\" — Epistaxis, GI, Menorrhagia, or High Risk):</b></li>\n<li class=\"l2\"><mark class=\"hl rx\"><b>IVIG (0.8–1 g/kg single dose)</b></mark> (fastest platelet rise, within 24–48 hrs!) <b>OR</b> Short-course <mark class=\"hl rx\"><b>Oral Prednisolone</b></mark> (2–4 mg/kg/day for 4–7 days).</li>\n<li class=\"l2\"><b>Life-Threatening Intracranial Hemorrhage (Rare &lt; 1%):</b> <mark class=\"hl rx\"><b>IVIG + High-Dose IV Methylprednisolone + Platelet Transfusion</b></mark> !</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u136\">← Case 25</button><button class=\"nv\" data-u=\"u138\">Case 27 →</button></nav></article><article class=\"view unit\" id=\"u138\" hidden style=\"--c:#00897b\"><button class=\"back\" data-p=\"6\">← Pediatrics</button><header class=\"uh\"><span class=\"ul\">Case 27</span><h1>Beta-Thalassemia Major, Sickle Cell Disease &amp; G6PD Deficiency (EGYPTIAN HEME CLASSICS)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Beta-Thalassemia+Major%2C+Sickle+Cell+Disease+%26+G6PD+Deficiency+%28EGYPTIAN+HEME+CLASSICS%29\">🔍 Search on Google</a></header><h3><b>1. Beta-Thalassemia Major (Cooley’s Anemia — </b><b>Extremely Common in Egypt!</b><b>)</b></h3><ul>\n<li class=\"l1\"><b>Pathology:</b> Autosomal recessive absent/severely reduced β-globin chains -&gt; excess α-chains precipitate -&gt; severe ineffective erythropoiesis &amp; extravascular hemolysis.</li>\n<li class=\"l1\"><b>Clinical Picture:</b> Presents at <b>4–6 months</b> (as fetal HbF drops!) with severe pallor, <b>failure to thrive</b>, massive <b>hepatosplenomegaly</b>, <b>\"Chipmunk Facies\" </b>(maxillary/frontal bossing from extramedullary hematopoiesis), <b>\"Hair-on-End\" skull X-ray</b>.</li>\n<li class=\"l1\"><b>Diagnosis:</b> Severe microcytic anemia + target cells/nucleated RBCs -&gt; <b>Hb Electrophoresis</b> shows <b>absent/near-zero HbA, markedly elevated HbF (&gt; 80–95%)</b>!</li>\n<li class=\"l1\"><b>Treatment:</b> Lifelong <b>regular packed RBC transfusions</b> (every 3–4 weeks to maintain pre-transfusion Hb 9–10.5 g/dL) <b>PLUS Iron Chelation</b> (<b>Deferasirox</b> oral or Deferoxamine SC once Ferritin &gt; 1,000 ng/mL to prevent fatal cardiac/hepatic/endocrine <b>Iron Overload</b>!). Curative: <b>Allogeneic Bone Marrow Transplant</b>.</li>\n</ul><h3><b>2. Sickle Cell Disease (HbSS)</b></h3><ul>\n<li class=\"l1\"><b>Pathology:</b> Single point mutation (Glutamate -&gt; Valine at position 6 of β-globin) -&gt; <b>HbS</b> polymerizes under hypoxia/dehydration/acidosis/cold -&gt; sickled RBCs cause microvascular <b>vaso-occlusion</b> and hemolysis.</li>\n<li class=\"l1\"><b>Acute Crises:</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Vaso-Occlusive Pain Crisis (VOC) &amp; Dactylitis (\"Hand-Foot Syndrome\"):</b> Earliest presentation in infants (&lt; 2 yrs); severe bone/extremity pain -&gt; <mark class=\"hl rx\"><b>Aggressive IV hydration + Opioids/NSAIDs + Warmth</b></mark> .</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><mark class=\"hl lab\"><b>Acute Chest Syndrome (LIFE-THREATENING!):</b></mark> Fever + chest pain + hypoxia + <mark class=\"hl mech\"><b>new pulmonary infiltrate on CXR</b></mark> -&gt; <mark class=\"hl rx\"><b>O2 + Broad-spectrum Antibiotics (Ceftriaxone + Azithromycin) + Simple/Exchange Blood Transfusion</b></mark> !</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Splenic Sequestration Crisis:</b> Sudden massive spleen enlargement + precipitous Hb drop + hypovolemic shock -&gt; <b>Urgent Blood Transfusion</b>!</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Aplastic Crisis (Parvovirus B19):</b> Sudden Hb drop with <b>LOW Reticulocytes</b>!</span></p>\n<ul>\n<li class=\"l1\"><b>Chronic Prevention:</b> <b>Hydroxyurea</b> (increases <b>HbF</b>, reduces crises!), <b>Oral Penicillin V prophylaxis</b> until age 5 (functional asplenia!), Pneumococcal/Meningococcal vaccines, <b>Transcranial Doppler (TCD)</b> screening for stroke!</li>\n</ul><h3><b>3. G6PD Deficiency (\"Favism\" / </b><b>Anemia El-Foul</b><b> — </b><b>Very Common in Egypt!</b><b>)</b></h3><ul>\n<li class=\"l1\"><b>Genetics:</b> <mark class=\"hl dx\"><b>X-linked recessive</b></mark> (predominantly affects <b>boys</b>!).</li>\n<li class=\"l1\"><b>Triggers:</b> <b>Fava beans (</b><i><b>Foul</b></i><b>)</b>, Infections (#1 trigger overall!), Oxidant drugs (<b>TMP-SMX, Primaquine, Dapsone, Nitrofurantoin, Rasburicase</b>), Naphthalene mothballs.</li>\n<li class=\"l1\"><b>Clinical Picture:</b> Sudden <b>acute intravascular hemolysis</b> 24–48 hours after eating fava beans -&gt; sudden pallor, <mark class=\"hl dx\"><b>jaundice</b></mark> , <b>dark red/black \"tea/cola\" urine (hemoglobinuria)</b>, abdominal/back pain, tachycardia!</li>\n<li class=\"l1\"><b>Labs:</b> Dropped Hb, elevated indirect bilirubin &amp; LDH, <b>Bite cells &amp; Heinz bodies</b> on smear; <b>G6PD enzyme level</b> (<i>CAUTION: Repeat G6PD assay 2–3 months AFTER recovery because young reticulocytes have falsely normal G6PD levels!</i>).</li>\n<li class=\"l1\"><b>Treatment:</b> Stop trigger + <b>IV hydration</b> + <b>Packed RBC transfusion</b> if severe symptomatic anemia + strict parent education list of forbidden foods/drugs!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u137\">← Case 26</button><button class=\"nv\" data-u=\"u139\">Case 28 →</button></nav></article><article class=\"view unit\" id=\"u139\" hidden style=\"--c:#00897b\"><button class=\"back\" data-p=\"6\">← Pediatrics</button><header class=\"uh\"><span class=\"ul\">Case 28</span><h1>Acute Lymphoblastic Leukemia (ALL — PEDIATRIC RED FLAGS)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Lymphoblastic+Leukemia+%28ALL+%E2%80%94+PEDIATRIC+RED+FLAGS%29\">🔍 Search on Google</a></header><h3><b>1. Definition &amp; Epidemiology</b></h3><p>Malignant clonal proliferation of immature lymphoid precursor cells (<b>lymphoblasts</b>) in bone marrow; <b>#1 malignancy of childhood</b> (peak <b>2–5 years</b>).</p><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><p><mark class=\"hl red\"><b>⚠ 2. Pediatric Red Flags (NEVER Dismiss Bone Pain as \"Growing Pains\"!)</b></mark></p></div></div><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><ul>\n<li class=\"l1\"><b>Bone / Joint Pain</b> (child refuses to walk / wakes up crying at night — often misdiagnosed as JIA or ARF!).</li>\n<li class=\"l1\"><b>Triad of Marrow Failure:</b> Pallor/fatigue (<mark class=\"hl lab\"><b> Anemia</b></mark> ), Petechiae/epistaxis (<b>Thrombocytopenia</b>), Persistent unexplained fever / recurrent infections</li>\n</ul>\n<p>(<mark class=\"hl lab\"><b> Neutropenia</b></mark> ).</p>\n<ul>\n<li class=\"l1\"><b>Extramedullary Infiltration:</b> Generalized painless <b>lymphadenopathy</b>, <b>hepatosplenomegaly</b>, painless <b>testicular enlargement</b>, anterior mediastinal mass (<mark class=\"hl lab\"><b> T-cell ALL</b></mark> -&gt; SVC syndrome/stridor!).</li>\n</ul></div></div><h3><b>3. Investigations &amp; Treatment</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl mech\"><b>CBC + Peripheral Smear:</b></mark> Anemia, Thrombocytopenia, high (or low/normal) WBC with <b>Circulating Blasts</b>!</li>\n<li class=\"l1\"><b>Gold Standard:</b> <b>Bone Marrow Aspiration &amp; Biopsy</b> (<b>≥ 20% Lymphoblasts</b>) + Flow Cytometry + Cytogenetics.</li>\n<li class=\"l1\"><b>Emergency Before Starting Chemo — Prevent Tumor Lysis Syndrome (TLS):</b> Aggressive IV hydration + <mark class=\"hl rx\"><b>Allopurinol</b></mark> (or <b>Rasburicase</b>) to prevent hyperuricemia, hyperkalemia, hyperphosphatemia, and hypocalcemia!</li>\n<li class=\"l1\"><b>Treatment:</b> Multi-agent risk-stratified <b>Chemotherapy</b> + CNS prophylaxis (<b>&gt; 85–90% cure rate</b> in children!).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u138\">← Case 27</button><button class=\"nv\" data-u=\"u140\">Case 29 →</button></nav></article><article class=\"view unit\" id=\"u140\" hidden style=\"--c:#00897b\"><button class=\"back\" data-p=\"6\">← Pediatrics</button><header class=\"uh\"><span class=\"ul\">Case 29</span><h1>Congenital Heart Diseases (VSD, ASD, PDA &amp; TETRALOGY OF FALLOT)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Congenital+Heart+Diseases+%28VSD%2C+ASD%2C+PDA+%26+TETRALOGY+OF+FALLOT%29\">🔍 Search on Google</a></header><h3><b>1. Acyanotic Left-to-Right Shunts (\"Pink Babies\")</b></h3><table class=\"t \"><tr class=\"hd\"><th><p><b>Lesion</b></p></th><th><p><b>Key Murmur &amp; Exam Clue</b></p></th><th><p><b>Clinical Course &amp; Treatment</b></p></th></tr><tr><td><p><mark class=\"hl lab\"><b>VSD</b></mark> <i>(Ventricular Septal Defect — </i><i><b>#1 Most Common CHD!</b></i><i>)</i></p></td><td><p><b>Harsh Holosystolic Murmur</b> at <b>Left Lower Sternal Border (LLSB)</b> +/- thrill</p></td><td><p>Small VSDs often close spontaneously! Large VSDs -&gt; <b>CHF at 4–8 weeks </b>(tachypnea, sweating during feeds, FTT) -&gt; Furosemide/ACE-i + <b>Surgical/Device Closure</b> (avoid Eisenmenger syndrome!).</p></td></tr><tr><td><p><b>ASD</b> <i>(Atrial Septal Defect)</i></p></td><td><p><b>Systolic Ejection Murmur</b> (pulmonic area) + <b>WIDE, FIXED SPLITTING OF S2!</b></p></td><td><p>Often asymptomatic until young adulthood; <b>Device/Surgical Closure</b> if significant shunt (Qp:Qs &gt; 1.5).</p></td></tr><tr><td><p><b>PDA</b> <i>(Patent Ductus Arteriosus — common in </i><i><b>Preterms &amp; Congenital Rubella</b></i><i>)</i></p></td><td><p><b>Continuous \"Machinery\" Murmur</b> below <b>Left Clavicle</b> + <b>Bounding pulses / Wide pulse pressure</b></p></td><td><p><i>Preterm:</i> Close with <mark class=\"hl rx\"><b>Indomethacin or Ibuprofen</b></mark> (or Acetaminophen)! <i>Term: </i>Transcatheter device closure. <i>(Note: Keep PDA OPEN with </i><i><b>Prostaglandin E1 [Alprostadil]</b></i><i> in ductal-dependent cyanotic lesions like Transposition of Great Arteries!)</i></p></td></tr></table><h3><b>2. Cyanotic Congenital Heart Disease: Tetralogy of Fallot (TOF)</b></h3><ul>\n<li class=\"l1\"><b>#1 Cyanotic CHD Beyond Infancy!</b></li>\n<li class=\"l1\"><b>4 Components (\"PROVE\"):</b> <b>P</b>ulmonary Stenosis (determines severity!), <b>R</b>ight Ventricular Hypertrophy (<b>Boot-Shaped Heart</b> on CXR!), <b>O</b>verriding Aorta, <b>V</b>SD.</li>\n<li class=\"l1\"><b>Clinical Picture:</b> Cyanosis, digital clubbing, harsh systolic ejection murmur at LUSB, <b>Hypoxic \"Tet Spells\"</b> (precipitated by crying/feeding/waking -&gt; sudden deep cyanosis, hyperpnea, syncope; older children instinctively <b>SQUAT</b> to increase SVR and force blood into pulmonary artery!).</li>\n<li class=\"l1\"><mark class=\"hl mech\"><b>EMERGENCY MANAGEMENT OF A \"TET SPELL\":</b></mark></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Knee-to-Chest Position</b> immediately (mimics squatting -&gt; increases SVR!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>100% Oxygen</b> + Calm the child (<b>IV/SC Morphine 0.1 mg/kg</b> -&gt; reduces hyperpnea &amp; infundibular spasm!).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><mark class=\"hl rx\"><b>IV Normal Saline bolus</b></mark> (10–20 mL/kg) + <b>IV Phenylephrine</b> (increases SVR) + <mark class=\"hl rx\"><b>IV Propranolol</b></mark> (relaxes RVOT spasm) + Sodium Bicarbonate if severe acidosis.</span></p>\n<ul>\n<li class=\"l1\"><b>Definitive:</b> Surgical complete repair (typically at 3–6 months).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u139\">← Case 28</button><button class=\"nv\" data-u=\"u141\">Case 30 →</button></nav></article><article class=\"view unit\" id=\"u141\" hidden style=\"--c:#00897b\"><button class=\"back\" data-p=\"6\">← Pediatrics</button><header class=\"uh\"><span class=\"ul\">Case 30</span><h1>Pediatric Type 1 Diabetes Mellitus (T1DM) &amp; Pediatric DKA</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pediatric+Type+1+Diabetes+Mellitus+%28T1DM%29+%26+Pediatric+DKA\">🔍 Search on Google</a></header><h3><b>1. Definition &amp; Clinical Presentation</b></h3><p>Autoimmune T-cell destruction of pancreatic β-cells (positive <b>Anti-GAD65, IA-2, IAA</b> antibodies) leading to absolute insulin deficiency.</p>\n<ul>\n<li class=\"l1\"><b>Classic Child Presentation:</b> Weeks of <b>polyuria, polydipsia, new-onset nocturnal enuresis (bedwetting in a previously dry child!)</b>, weight loss despite polyphagia — or abruptly in <mark class=\"hl lab\"><b>DKA</b></mark> (vomiting, abdominal pain, Kussmaul breathing, fruity breath, dehydration)!</li>\n</ul><h3><b>2. CRITICAL DIFFERENCES IN PEDIATRIC DKA MANAGEMENT (Prevent Fatal Cerebral Edema!)</b></h3><p><i>(Cerebral edema is the #1 cause of DKA mortality in children! Follow strict </i><mark class=\"hl lab\"><i><b>ISPAD</b></i></mark><i> pediatric safety rules:)</i></p>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><mark class=\"hl rx\"><b>NO Insulin Bolus!</b></mark> Start <mark class=\"hl rx\"><b>IV Regular Insulin Infusion at 0.05 – 0.1 U/kg/hr</b></mark> ONLY <mark class=\"hl rx\"><b>1 hour AFTER starting IV fluids!</b></mark> <i>(An initial IV insulin bolus increases cerebral edema risk!)</i></span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Avoid Rapid/Excessive Fluid Boluses Unless in True Shock:</b> Give <b>10–20 mL/kg 0.9% Normal Saline</b> over 30–60 min ONLY if peripheral hypoperfusion/shock; then calculate slow maintenance + deficit replacement evenly over <b>48 hours</b>!</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><mark class=\"hl rx\"><b>Check Potassium (K+) Before Insulin:</b></mark> Add <b>20–40 mEq/L KCl</b> to IV fluids once urine output is confirmed and K+ &lt; 5.5 mEq/L (hold insulin if K+ &lt; 3.3!).</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Watch for Cerebral Edema Warning Signs (4–12 hrs into treatment):</b> Sudden severe <b>headache</b>, <b>bradycardia + hypertension (Cushing’s triad)</b>, vomiting, irritability, unequal pupils, declining Glasgow Coma Scale -&gt; <mark class=\"hl rx\"><b>IMMEDIATE IV Mannitol (0.5–1 g/kg over 15 min) or 3% Hypertonic Saline (2.5–5 mL/kg)</b></mark> + elevate head of bed 30°!</span></p>\n<p class=\"num\"><span class=\"n\">5.</span><span class=\"nt\"><b>Avoid Sodium Bicarbonate</b> (strongly linked to cerebral edema!).</span></p><h3><b>3. Chronic T1DM Management</b></h3><ul>\n<li class=\"l1\"><b>Basal-Bolus Multiple Daily Injections (MDI):</b> Basal (<b>Glargine / Detemir / Degludec</b>) + Mealtime Rapid-acting (<b>Lispro / Aspart / Glulisine</b>) OR Insulin Pump + Carbohydrate counting + CGM/glucometer monitoring (Target HbA1c <b>&lt; 7.0%</b>). Screen annually for <b>Celiac Disease</b> and <b>Autoimmune Thyroiditis</b>!</li>\n</ul>\n<p class=\"muted\"><i>End of Part 6B — Pediatrics (30 Cases Complete!</i></p><nav class=\"un\"><button class=\"nv\" data-u=\"u140\">← Case 29</button></nav></article>"});
